window.__LEX={"G3400":"<h1>milion</h1>\n<p>Strong n° 3400 <i>Prononciation [mil'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un mille, chez les Romains la distance de mille pas ou huit stades (mesure grecque de 185 m), le mille faisant environ 1480 mètres, soit une longueur proche du 'mile' anglais</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μίλιον, ου (τὸ)</b> le mille romain, espace de mille pas, <i>équivalent à 8 stades,</i> POL. <i>34, 11, 8 ; 34, 12, 3 ;</i> STR. <i>285, 322 ;</i> PLUT. <i>Cic. 32, etc</i>.<br><span><b>Étym</b>. <i>lat</i>. millia.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μιλιον - μίλιον</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G3401":"<h1>mimeomai</h1>\n<p>Strong n° 3401 <i>Prononciation [mim-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>imiter, suivre</li>\n<li>mimer, imiter par une pantomime</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μιμέομαι-οῦμαι</b> <span>[ῑ]</span><br><b>   I</b> <i>act. :</i><br><b>      1</b> imiter, <i>acc. au sens phys</i>. imiter (la voix, le geste, les cris, <i>etc</i>.) HH. <i>Ap. 163 ;</i> PD. <i>P. 12, 21 ;</i> ESCHL. <i>Ch. 564 ;</i> PLAT. <i>Crat. 423</i> c ; PLUT. <i>M. 674</i> b ; <i>au mor</i>. imiter (les actions, les vertus, <i>etc</i>.) BATR. <i>7 ;</i> THC. <i>2, 37 ; en mauv. part,</i> EUR. <i>El. 1037 ;</i> PLAT. <i>Pol. 293</i> e, PHIL. <i>40</i> c ;<br><b>      2</b> <i>particul</i>. mimer, imiter par une pantomime, PLAT. <i>Rsp. 605</i> c ; <i>en parl. de danse,</i> XÉN. <i>Conv. 2, 21, 22, An. 6, 1, 9 ;</i><br><b>   II</b> <i>pass</i>. être imité, <i>aux temps suiv. : part. prés</i>. μιμούμενος, PLAT. <i>Rsp. 604</i> e ; <i>part. fut</i>. μιμηθησόμενον, PLAT. <i>Rsp. 599</i> a ; <i>part. ao</i>. μιμηθέν, PLAT. <i>Leg. 668</i> b ; <i>part. pf</i>. μεμιμημένος, HDT. <i>2, 78, 86 ;</i> PLAT. <i>Crat. 425</i> d.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. 2 sg</i>. μίμεο, SIM. <i>fr. 29. Fut. dor</i>. μιμάσομαι <span>[ᾱ]</span> ECPHANT. (STOB. <i>48, 64). Ao. 2 sg</i>. ἐμιμήσαο, HDT. <i>3, 32. Pf. dor</i>. μεμίμαμαι <span>[ᾱ]</span> ECPHANT. (STOB. <i>48, 64</i>). — <span>[ῐ]</span> SIB. <i>2, 146</i>.<br><span><b>Étym</b>. μῖμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μιμεομαι - μιμέομαι</font>\n<br><br>vient de 'mimos' (une « mimique »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Thessaloniciens (2)</li>\n<li>Hébreux (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3402":"<h1>mimetes</h1>\n<p>Strong n° 3402 <i>Prononciation [mim-ay-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un imitateur</li>\n<li>en mauvaise part : comédien, charlatan</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μιμητής, οῦ (ὁ)</b> <span>[ῑ]</span><br><b>      1</b> imitateur, XÉN. <i>Mem. 1, 6, 3 ;</i> PLAT. <i>Rsp. 566</i> d, <i>etc. ;</i><br><b>      2</b> qui représente les caractères : poète <i>ou</i> acteur, ARSTT. <i>Poet. 3, 4 ;</i> PLUT. <i>M. 717</i> c, <i>etc. ;</i><br><b>      3</b> <i>en mauv. part :</i> comédien, charlatan, PLAT. <i>Soph. 235</i> a, <i>Pol. 303</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. μιμητάς, ANTH. <i>7, 191</i>.<br><span><b>Étym</b>. μιμέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μιμητης - μιμητής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3403":"<h1>mimnesko</h1>\n<p>Strong n° 3403 <i>Prononciation [mim-nace'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se rappeler, se souvenir\n<ol type=\"a\">\n<li>être rappelé ou revenir à l'esprit, se souvenir</li>\n<li>avoir en mémoire</li>\n<li>se rappeler d'une chose</li>\n<li>être attentif à</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μιμνῄσκω</b> <span>(<i>f</i>. μνήσω, <i>ao</i>. ἔμνησα, <i>pf. inus</i>.)</span> faire souvenir : τινός, OD. <i>14, 170,</i> de qqn ; τινά τινος, IL. <i>1, 407, etc. ;</i> OD. <i>3, 103,</i> qqn de qqe ch. ; τι, EUR. <i>Alc. 878,</i> rappeler qqe ch. ;<br><b><i>Moy</i>. μιμνῄσκομαι</b> <span>(<i>f</i>. μνήσομαι <i>ou</i> μνησθήσομαι, <i>ao.1</i> ἐμνησάμην, <i>plus souv</i>. ἐμνήσθην ; <i>pf</i>. μέμνημαι ; <i>pl.q.pf</i>. ἐμεμνήμην, <i>f. ant</i>. μεμνήσομαι)</span><br><b>      1 <i>intr.</i></b> se mettre dans l’esprit, penser à : τινος, <i>gén</i>. HOM. <i>etc. ; avec l’inf</i>. μέμνηντο ἀλεξέμεναι φόνον, IL. <i>17, 364,</i> ils songeaient à repousser la mort ; <i>particul. au pf. et au pl.q.pf. au sens du prés. et de l’impf</i>. je me souviens, je me souvenais, <i>avec le gén</i>. IL. <i>11, 546, etc. ;</i> ATT. ; <i>avec l’acc</i>. IL. <i>6, 222, etc. ;</i> ATT. ; <i>avec une prép</i>. ἀμφί τινι, OD. <i>4, 151 ;</i> περί τινος, OD. <i>7, 192,</i> se souvenir de qqn <i>ou</i> de qqe ch. ; <i>avec l’inf</i>. ESCHL. <i>Suppl. 205 ;</i> XÉN. <i>Cyr. 8, 6, 6, etc</i>. se souvenir de faire qqe ch. ; <i>avec</i> ὅτι, XÉN. <i>Cyr. 3, 1, 27,</i> se souvenir que, <i>etc. ; avec un part</i>. μέμνημαι ἀκούσας σου, XÉN. <i>Cyr. 1, 6, 3,</i> je me souviens de t’avoir entendu ; <i>avec un rég. accompagné d’un part</i>. μέμνημαι καὶ τοῦτό σου λέγοντος, XÉN. <i>Cyr. 1, 6, 8,</i> je me souviens de t’avoir entendu dire cela aussi ; <i>abs</i>. ἐς ὃ ἐμέμνηντο, THC. <i>5, 66,</i> de mémoire d’homme ; <i>au part. dans les exhortations, ordres, etc. :</i> Αἰνείαο δ' ἐπαῗξαι μεμνημένος ἵππων, IL. <i>5, 263,</i> souviens-toi de te jeter sur les chevaux d’Énée ;<br><b>      2 <i>tr.</i></b> rappeler le souvenir de, faire mention de, <i>gén</i>. OD. <i>4, 331 ;</i> THC. <i>2, 45, etc. ; acc</i>. PD. <i>I. 8, 59 ; avec περί et le gén</i>. HDT. <i>1, 36 ;</i> THC. <i>1, 10 ;</i> XÉN. <i>Ages. 5, 4, etc. ;</i> πρός τινα περί τινός τι, XÉN. <i>Cyr. 8, 2, 12 ;</i> τί τινι περί τινος, PLAT. <i>Lach. 200</i> d, rappeler qqe ch. à qqn au sujet de qqe ch. ; <i>au pass</i>. être rappelé au souvenir, SPT. <i>Sir. 16, 17 ; Ezech. 18, 22 ;</i> NT. <i>Ap. 10, 31 ; Apoc. 16, 19 ;</i><br><b>      3</b> <i>p. suite,</i> penser à, s’occuper de, prendre soin de, <i>gén</i>. OD. <i>18, 267</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao. dor</i>. ἔμνασα <span>[νᾱ]</span> PD. <i>P. 11, 13. Pass. impf. 2 sg. poét</i>. μιμνήσκεο, IL. <i>22, 268. Ao. dor</i>. ἐμνάσθην, PD. <i>O. 7, 61 ; N. 9, 10 ;</i> EUR. <i>El. 745. Pf. dor</i>. μέμναμαι <span>[νᾱ]</span> PD. <i>O. 6, 11 ;</i> EUR. <i>El. 188, etc. ; 2 sg. épq</i>. μέμνηαι, IL. <i>21, 442 ;</i> μέμνῃ, OD. <i>24, 115 ; dor</i>. μέμνᾳ, THCR. <i>Idyl. 5, 116 ; impér. 2 sg. poét</i>. μέμνεο, ORPH. <i>Lith. 603 ;</i> ANTH. <i>App. 310, 5 ; 3 sg. dor</i>. μεμνάσθω, PD. <i>N. 11, 15 ; opt. 3 sg. épq</i>. μεμνέῳτο, IL. <i>23, 361 ; 3 pl. dor</i>. μεμναίατο, PD. <i>fr. 277, inf. dor</i>. μεμνᾶσθαι, PD. <i>O. 6, 92 ; part. dor</i>. μεμναμένος <span>[ᾱ]</span> PD. <i>N. 7, 80. Pl.q.pf. dor. 3 pl</i>. ἐμέμναντο, PD. <i>I. 8, 27 ; ion</i>. ἐμεμνέατο, HDT. <i>2, 104. Moy. fut. 2 sg. poét</i>. μνήσεαι, THGN. <i>100 ; ao. dor</i>. μνασάμην <span>[νᾱ]</span> ESCHL. <i>Suppl. 51. Ao. itér. 3 sg</i>. μνησάσκετο, IL. <i>11, 566</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *mneh₂-, rappeler, <i>probabl. de la</i> R. *men-, penser ; <i>cf</i>. *μένω², μένος, μαίνω, <i>sscr</i>. a-mnāsiṣuḥ « ils mentionnèrent » ; <i>v</i>. μνάομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μιμνησκω - μιμνῄσκομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G3404":"<h1>miseo</h1>\n<p>Strong n° 3404 <i>Prononciation [mis-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>haïr, poursuivre avec haine, détester, avoir horreur, être un objet de haine</li>\n<li>être haï, détesté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μισέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἐμίσησα, <i>pf</i>. μεμίσηκα)</span> <span>[ῑ]</span> haïr, détester, <i>acc</i>. ESCHL. <i>Pr. 1067 ;</i> SOPH. <i>El. 357 ;</i> PLUT. <i>M. 537</i> a, <i>etc. ; avec l’inf</i>. avoir horreur de, EUR. <i>Rhes. 333 ; avec une prop. inf</i>. avoir horreur que, IL. <i>17, 272 ; au pass</i>. être haï, être un objet de haine, ESCHL. <i>Pr. 45 ;</i> SOPH. <i>Aj. 818 ;</i> ὑπό τινος, THC. <i>8, 83 ;</i> XÉN. <i>Cyr. 8, 2, 1,</i> être haï par qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy. au sens pass</i>. μισήσομαι, EUR. <i>Tr. 659 ; Ion 597, 611 ;</i> BABR. <i>13 ;</i> PHILSTR. <i>V. Ap. 251</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μισεω - μισέω</font>\n<br><br>vient du mot primaire 'misos' (haine)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n41 fois dans 37 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (1)</li>\n<li>Luc (7)</li>\n<li>Jean (12)</li>\n<li>Romains (2)</li>\n<li>Ephésiens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Jean (5)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G3405":"<h1>misthapodosia</h1>\n<p>Strong n° 3405 <i>Prononciation [mis-thap-od-os-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>payement de salaires dus, dédommagement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μισθαποδοσία, ας (ἡ)</b> juste rétribution, salaire dû, NT. <i>Hebr. 2, 2 ; 10, 35</i>.<br><span><b>Étym</b>. μισθαποδότης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μισθαποδοσια - μισθαποδοσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G3406":"<h1>misthapodotes</h1>\n<p>Strong n° 3406 <i>Prononciation [mis-thap-od-ot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui paie le salaire, le rémunérateur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μισθ·αποδότης, ου (ὁ)</b> <span>[ᾰ]</span> qui paye un salaire dû, une juste rémunération, NT. <i>Hebr. 11, 6</i>.<br><span><b>Étym</b>. μισθός, ἀποδίδωμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μισθαποδοτης - μισθαποδότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3407":"<h1>misthios</h1>\n<p>Strong n° 3407 <i>Prononciation [mis'-thee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>employés en louage, engagés</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μίσθιος, α, ον :<br>      1</b> pris à gages, salarié, mercenaire, PLUT. <i>Lyc. 16 ;</i><br><b>      2</b> qu’on fait moyennant salaire, ANTH. <i>6, 283</i>.<br><span><b>Étym</b>. μισθός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μισθιος - μίσθιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G3408":"<h1>misthos</h1>\n<p>Strong n° 3408 <i>Prononciation [mis-thos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dû payé pour un travail\n<ol type=\"a\">\n<li>salaire, gages</li>\n</ol>\n</li>\n<li>récompense : utilisé pour le fruit qui résulte naturellement d'un dur travail et de l'effort\n<ol type=\"a\">\n<li>dans les deux sens de récompenses et châtiments</li>\n<li>des récompenses que Dieu accorde, ou accordera, aux bonnes actions ou efforts</li>\n<li>de punitions : le salaire du crime, de l'iniquité</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μισθός, οῦ (ὁ)</b> salaire, <i>particul. :</i><br><b>      1</b> gages, paye, honoraires, IL. <i>10, 304, etc. ;</i> OD. <i>4, 525, etc. ;</i> ἐπὶ μισθῷ, HDT. <i>8, 137 ;</i> LUC. <i>Nigr. 25 ; ou simpl</i>. μισθοῦ, SOPH. <i>Tr. 560 ;</i> XÉN. <i>Cyr. 3, 2, 7, etc</i>. moyennant salaire ; μισθὸν λαμϐάνειν, EUR. <i>I.T. 593 ;</i> PLUT. <i>M. 786</i> c ; LUC. <i>V. auct. 3, etc. ; ou</i> δέχεσθαι, XÉN. <i>Ap. 16,</i> recevoir un salaire, πράττεσθαι, PD. <i>O. 10, 35,</i> gagner un salaire ; φέρειν, THC. <i>8, 97 ;</i> AR. <i>Ach. 66 ; ou</i> φέρεσθαι, XÉN. <i>Œc. 1, 4, m. sign</i>. διδόναι, EUR. <i>H.f. 19 ; ou</i> τελεῖν, AR. <i>Ran. 13,</i> donner <i>ou</i> payer un salaire ;<br><b>      2</b> solde militaire, THC. <i>1, 143 ; 4, 124 ; 6, 8, etc. ;</i> XÉN. <i>An. 7, 3, 13, etc. ; Hell. 1, 5, 7, etc. ;</i><br><b>      3</b> honoraires de médecin, ARSTT. <i>Pol. 3, 16, 17 ;</i><br><b>      4</b> loyer : ἐν μισθῷ οἰκεῖν, XÉN. <i>Conv. 4, 4 (conj</i>. ἐν μισθωταῖς) habiter à loyer ;<br><b>      5</b> récompense, rémunération, <i>en gén</i>. PLAT. <i>Rsp. 363</i> d, <i>etc. ; d’où en mauv. part,</i> peine, châtiment, ESCHL. <i>Ag. 1261 ;</i> SOPH. <i>Ant. 221, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans une inscr. att</i>. μισσθός, CIA. <i>2, add. 834 b, 1, 11 (4<sup>e</sup> siècle av. J.C.) ; v. Meisterh. p. 69</i> d.<br><span><b>Étym</b>. <i>indo-europ</i>. *misd<sup>h</sup>-, salaire ; <i>cf. sscr</i>. mīḍhá- « prix à un concours, concours », <i>zend</i>. miždha, <i>gotique</i> mizdo « salaire », <i>all</i>. Miete.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μισθος - μισθός</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n29 fois dans 28 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (4)</li>\n<li>1 Timothée (1)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (2)</li>\n<li>2 Jean (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G3409":"<h1>misthoo</h1>\n<p>Strong n° 3409 <i>Prononciation [mis-tho'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre en location, prendre à gages</li>\n<li>louer, engager des ouvriers, payer un salaire d'où embaucher</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μισθόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἐμίσθωσα, <i>pf</i>. μεμίσθωκα)</span><br><b>      1</b> donner à loyer, τινά τινι, DÉM. <i>327, 24,</i> engager une personne au service d’une autre ; τινὶ νηὸν ἐξεργάσασθαι, HDT. <i>2, 180,</i> confier à qqn, moyennant un prix convenu, la construction d’un temple ;<br><b>      2</b> prendre à loyer, <i>d’où au pass</i>. être pris à loyer <i>ou</i> à gages, être gagé, salarié, HDT. <i>9, 37 ;</i> XÉN. <i>An. 1, 3, 1 ;</i> PLAT. <i>Leg. 800</i> e ;<br><b><i>Moy.</i></b> :<br><b>      1</b> prendre à loyer, à gages, gager, soudoyer, <i>acc</i>. HDT. <i>1, 24 ; 9, 34 ;</i> THC. <i>4, 52 ;</i> DÉM. <i>236, 22, etc. ;</i><br><b>      2</b> entreprendre à forfait, <i>acc</i>. DÉM. <i>1253, 15</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. prés. ind. 3 pl. ion</i>. -εῦνται, HDT. <i>3, 131</i>.<br><span><b>Étym</b>. μισθός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μιστοω - μισθόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G3410":"<h1>misthoma</h1>\n<p>Strong n° 3410 <i>Prononciation [mis'-tho-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le prix pour lequel une chose est laissée ou louée\n<ol type=\"a\">\n<li>du prix d'une prostituée</li>\n</ol>\n</li>\n<li>ce qui est laissé ou loué pour un prix, telle une maison, une demeure, un logis</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μίσθωμα, ατος (τὸ) :<br>      1</b> paye, solde, salaire, HDT. <i>2, 180 ;</i> ISOCR. <i>145</i> c ; DÉM. <i>379, 20 ;</i> MACH. (ATH. <i>581</i> a) ; LUC. <i>D. mer. 6, 3, etc. ;</i><br><b>      2</b> loyer d’une maison, NT. <i>Ap. 28, 30</i>.<br><span><b>Étym</b>. μ. μισθόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μισθωμα - μίσθωμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3411":"<h1>misthotos</h1>\n<p>Strong n° 3411 <i>Prononciation [mis-tho-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui est loué, un mercenaire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μισθωτός, ή, όν :<br>   I</b> <i>adj</i>. pris à gages, mercenaire, HDT. <i>3, 45, etc. ; en parl. de maisons,</i> pris à loyer, loué, XÉN. <i>Conv. 4, 4 ;</i> ATH. <i>212</i> d ;<br><b>   II</b> <i>subst. :</i><br><b>      1</b> ὁ μ. serviteur à gages, AR. <i>Av. 1152 ;</i> PLAT. <i>Rsp. 371</i> e ; <i>joint à</i> θῆτες, PLAT. <i>Pol. 290</i> a ; <i>p. opp. à</i> οἰκέται, DÉM. <i>1199, 21 ;</i><br><b>      2</b> soldat, mercenaire, HDT. <i>1, 61 ;</i> THC. <i>5, 6 ;</i><br><b>      3</b> agent salarié, espion, DÉM. <i>238, 21 ; 242, 27, etc</i>.<br><span><b>Étym</b>. μισθόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μισθωτος - μισθωτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G3412":"<h1>Mitulene</h1>\n<p>Strong n° 3412 <i>Prononciation [mit-oo-lay'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Mytilène = « mutilée »\n<ol><li>ville entre Assos et Chios, capitale de l'île grecque appelée autrefois Lesbos, dans la mer Egée. De nos jours c'est l'île entière qui s'appelle Mytilène</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Μιτυλήνη, ης (ἡ)</b> <span>[ῐῠ]</span> Mitylène (<i>auj</i>. Mytilíni) <i>v. de Lesbos,</i> STR. <i>440 ;</i> PLUT. <i>Pomp. 42, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. Μιτυλάνα <span>[ᾱᾱ]</span> THCR. <i>Idyl. 7, 52 et 61 ;</i> ANTH. <i>7, 81, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μιτυληνη - Μιτυλήνη</font>\n<br><br>pour 'mutilene' (abondant en coquillages)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3413":"<h1>Michael</h1>\n<p>Strong n° 3413 <i>Prononciation [mikh-ah-ale']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Michel (Angl. Michael) = « qui est comme Dieu »\n<ol><li>le premier des archanges qui est supposé être l'ange gardien des Israélites</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Μιχαήλ (ὁ)</b> <i>indécl</i>. Michael (Michel) :<br><b>      1</b> <i>archange,</i> ANTH. <i>1, 32, etc. ;</i><br><b>      2</b> <i>empereur byzantin,</i> ANTH. <i>1, 107 ; 9, 815 ;</i><br><b>      3</b> <i>écrivain,</i> ANTH. <i>App. 52, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μιχαηλ</font> &lt; מיכאל - <font face=\"Georgia\">Μιχαήλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT).\n<ul>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3414":"<h1>mna</h1>\n<p>Strong n° 3414 <i>Prononciation [mnah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dans l'A.T., la mine avait un poids de 300 sicles</li>\n<li>Dans le N.T., poids et somme d'argent d'une valeur de 100 drachmes, un talent valant 100 mines, une mine valait environ 300 grammes</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μνᾶ, ᾶς (ἡ)</b> mine :<br><b>      1</b> <i>poids (masse ?) de 100 drachmes (un peu moins d’un demi-kilogr</i>.) GAL. <i>13, 978, 980 ;</i><br><b>      2</b> <i>monnaie de 100 drachmes ; 10 mines d’argent font une mine d’or, 60 mines d’argent font un talent,</i> THC. <i>3, 50 ;</i> XÉN. <i>Vect. 4, 14, 15 ; An. 1, 4, 13, etc. ;</i> PLAT. <i>Leg. 936</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. seul. la forme contracte :</i> μναῖ, CIA. <i>2, 807, b 100 (330 av. J.C</i>.) ; μνῶν, CIA. <i>1, 9 (464/457 av. J.C.) ; v. Meisterh. p. 97, 20. Ion</i>. μνέα, HDT. <i>2, 180 ;</i> LUC. <i>Syr. 48</i>.<br><span><b>Étym</b>. <i>emprunt sémit. ; cf. hébr</i>. māne.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μνα - μνᾶ</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 6 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (9)</li>\n</ul>\n</td></tr>\n</table>","G3415":"<h1>mnaomai</h1>\n<p>Strong n° 3415 <i>Prononciation [mnah'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se souvenir, se rappeler\n<ol type=\"a\">\n<li>être rappelé ou remis à l'esprit</li>\n<li>avoir en mémoire</li>\n<li>se rappeler d'une chose</li>\n<li>être attentif à</li>\n</ol>\n</li>\n</ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μνάομαι-ῶμαι</b>, penser à, <i>d’où :</i><br><b>   I</b> (<i>prés</i>. μνάομαι-ῶμαι, <i>impf</i>. ἐμναόμην-ώμην, <i>f</i>. μνήσομαι, <i>ao</i>. ἐμνησάμην, <i>pf</i>. μέμνημαι <i>commun avec</i> μιμνῄσκομαι) :<br><b>      1</b> penser à, s’occuper de : περί τινος, OD. <i>6, 192,</i> de qqe ch. ;<br><b>      2</b> se souvenir de, <i>gén</i>. IL. <i>4, 172 ; 9, 647, etc. ;</i> OD. <i>10, 177, etc. ;</i><br><b>   II</b> (<i>seul. au prés., à l’impf., à l’impf. itér. v. ci-dessous</i>) désirer, <i>particul. :</i><br><b>      1</b> désirer comme femme, rechercher en mariage, <i>acc</i>. OD. <i>1, 39, 248 ; 6, 34, etc. ;</i> μνᾶσθαι γάμον, LUC. <i>Pseud. 28,</i> rechercher en mariage ;<br><b>      2</b> désirer, convoiter, ambitionner, rechercher, <i>en gén., acc</i>. HDT. <i>1, 96, 205 ;</i> HDN <i>2, 7, 11 ; 7, 9, 24</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Au premier sens : seul. prés</i>. OD. <i>16, 77 ; part</i>. μνώμενος, THCR. <i>Epigr. 15, 4 ; épq</i>. μνωόμενος, OD. <i>4, 106, et impf. 3 pl</i>. ἐμνώοντο, IL. <i>2, 686, et</i> μνώοντο, IL. <i>11, 71 ; 16, 697, 771. — Au deuxième sens : prés. 2 sg. épq</i>. μνάᾳ <span>[ᾱᾳ]</span> (<i>p</i>. μνᾷ = μνάῃ) OD. <i>16, 431 ; inf. épq</i>. μνάασθαι <span>[ᾱα]</span> OD. <i>1, 39 ; part. ion</i>. μνεώμενος, HDT. <i>1, 96. Impf. 3 pl</i>. μνώοντο, OD. <i>11, 288, ou</i> ἐμνώοντο, THCR. <i>Idyl. 27, 22. Impf. itér. 3 sg</i>. μνάσκετο, OD. <i>20, 290</i>.<br><span><b>Étym</b>. μιμνῄσκω ; <i>p. le développement du deuxième sens</i> « rappeler <i>au sujet de mariage</i> », <i>cf. lat</i>. mentionem fac, PLAUT. <i>Aul. 685</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μναομαι - μνάομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 21 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (6)</li>\n<li>Jean (3)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3416":"<h1>Mnason</h1>\n<p>Strong n° 3416 <i>Prononciation [mnah'-sohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Mnason = « qui se souvient »\n<ol><li>un Chrétien venant de Chypre, un nom commun en Grèce</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Μνάσων, ωνος (ὁ)</b> Mnasôn, <i>h</i>. LUC. <i>Philops. 22</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μνασων - Μνάσων</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3417":"<h1>mneia</h1>\n<p>Strong n° 3417 <i>Prononciation [mni'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souvenir, mémoire, faire mention de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μνεία, ας (ἡ) :<br>      1</b> souvenir ; μνείαν ἔχειν τινός, SOPH. <i>El. 392 ;</i> PLAT. <i>Menex. 244</i> a, <i>etc</i>. avoir souvenir de qqe ch. ; κατά γε τὴν μνείαν ἐμήν, EL. <i>N.A. 12, 32 ; V.H. 6, 1,</i> selon mon souvenir ;<br><b>      2</b> mention : μνείαν ποιεῖσθαί τινος, PLAT. <i>Phædr. 254</i> a, <i>ou</i> περί τινος, PLAT. <i>Prot. 317</i> e ; ESCHN. <i>23, 5,</i> faire mention de qqn <i>ou</i> de qqe ch. ;<br><b>      3</b> <i>t. eccl</i>. commémoration, anniversaire, NYSS. <i>3, 733 Migne</i>.<br><span><b>Étym</b>. μνάομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μνεια - μνεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Timothée (1)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G3418":"<h1>mnema</h1>\n<p>Strong n° 3418 <i>Prononciation [mnay'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>monument ou mémorial pour perpétuer le souvenir d'une personne ou d'un événement</li>\n<li>un monument funéraire</li>\n<li>un sépulcre ou tombe, un tombeau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μνῆμα, ατος (τὸ) :<br>   I</b> signe pour rappeler un souvenir, <i>particul. :</i><br><b>      1</b> emblème <i>ou</i> monument commémoratif, PD. <i>O. 3, 16, etc. ;</i> SIM. (THC. <i>1, 132</i>) ; ESCHL. <i>Pr. 841 ;</i> SOPH. <i>Aj. 1210, etc. ;</i><br><b>      2</b> tombeau, SIM. (HDT. <i>7, 228) ; plur. au sens du sg</i>. XÉN. <i>Hell. 3, 12, 14 ;</i> EUR. <i>Suppl. 663 ;</i> DÉM. <i>297, 15, etc. ;</i><br><b>   II</b> souvenir, THGN. <i>112</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. μνᾶμα, PD. <i>O. 3, 16 ; I. 7, 63 ;</i> SIM. (THC. <i>1, 132</i>) penser ; <i>cf</i>. μνάομαι.<br><span><b>Étym</b>. μιμνῄσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μνημα - μνῆμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Actes (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3419":"<h1>mnemeion</h1>\n<p>Strong n° 3419 <i>Prononciation [mnay-mi'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tout objet visible pour préserver ou rappeler la mémoire d'une personne ou d'un événement\n<ol type=\"a\">\n<li>mémorial, monument, spécifiquement un monument funéraire</li>\n</ol>\n</li>\n<li>un sépulcre, un tombeau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μνημεῖον, ου (τὸ) :<br>   I</b> souvenir, HDT. <i>2, 126 ;</i> THC. <i>2, 41 ;</i> PLAT. <i>Tim. 26</i> b, <i>etc. ;</i><br><b>   II</b> signe pour rappeler un souvenir, monument commémoratif, <i>particul. en parl. d’un mort,</i> urne contenant les cendres d’un mort, SOPH. <i>El. 1126 ;</i> tombeau, XÉN. <i>Hell. 2, 4, 17, etc. ;</i> PLAT. <i>Rsp. 414</i> a ; EUR. <i>I.T. 702, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. μνημήϊον, HDT. <i>l. c. ;</i> A. RH. <i>3, 1206, etc. ; dor</i>. μναμήϊον <span>[ᾱ]</span> PD. <i>P. 5, 49</i>.<br><span><b>Étym</b>. μνήμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μνημειον - μνημεῖον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 38 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (9)</li>\n<li>Luc (9)</li>\n<li>Jean (16)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3420":"<h1>mneme</h1>\n<p>Strong n° 3420 <i>Prononciation [mnay'-may]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mémoire, souvenir</li>\n<li>faire mention : se souvenir d'une chose, rappeler en mémoire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μνήμη, ης (ἡ) :<br>   I</b> mémoire, souvenir, <i>càd. :</i><br><b>      1</b> action de se souvenir, THGN. <i>798, 1114 ;</i> ATT. ;<br><b>      2</b> le souvenir lui-même, ce qui reste dans l’esprit, HDT. <i>4, 144 ;</i> ATT. ; μνήμην ἔχειν τινός, SOPH. <i>O.R. 1246, O.C. 509, El. 346,</i> conserver <i>ou</i> rappeler le souvenir de qqe ch. ; <i>au plur</i>. LYS. <i>198, 8, etc. ;</i> μνήμην ποιεῖσθαι, THC. <i>2, 54,</i> rappeler son souvenir, se rappeler ; μνήμην ποιεῖν, ARSTT. <i>Rhet. 3, 12, 4,</i> faire que qqn se souvienne ;<br><b>      3</b> faculté de se souvenir, mémoire, ATT. ; εἰπεῖν μνήμης ὕπο, SOPH. <i>O.R. 1131,</i> dire de mémoire ; ἐν μνήμῃ λαμϐάνειν, PLAT. <i>Tim. 26</i> b, déposer dans sa mémoire ; φυλάττειν τῇ μνήμῃ, PLAT. <i>Leg. 783</i> c, avoir <i>ou</i> conserver dans sa mémoire ; <i>t. eccl</i>. commémoration, anniversaire, BAS. <i>4, 484 ;</i> NYSS. <i>3, 728 Migne ;</i><br><b>   II</b> mention : μνήμην ποιεῖσθαί τινος, HDT. <i>1, 15 ;</i> περί τινος, POL. <i>2, 7, 12 ; ou</i> ὑπέρ τινος, POL. <i>2, 71, 1 ;</i> DS. <i>15, 52,</i> faire mention de qqn <i>ou</i> de qqe ch. ;<br><b>   III</b> signe <i>ou</i> objet pour rappeler un souvenir, <i>particul. :</i><br><b>      1</b> prescription, précepte, PLAT. <i>Leg. 741</i> c ; ARSTT. <i>Rhet. 1, 5 ;</i><br><b>      2</b> documents, archives : βασίλειος, HDN <i>4, 8,</i> dépôt des archives royales, cabinet du roi.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. μνάμα <span>[νᾱ]</span>, ANTH. <i>fr. adesp. 108 Bgk</i>.<br><span><b>Étym</b>. μιμνῄσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μνημη - μνήμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3421":"<h1>mnemoneuo</h1>\n<p>Strong n° 3421 <i>Prononciation [mnay-mon-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être attentif à, se souvenir de, rappeler à l'esprit\n<ol type=\"a\">\n<li>avoir en mémoire, garder à l'esprit</li>\n</ol>\n</li>\n<li>faire mention de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μνημονεύω</b> <span>(<i>f</i>. εύσω, <i>ao</i>. ἐμνημόνευσα, <i>pf. sans redoubl</i>. ἐμνημόνευκα)</span><br><b>      1</b> rappeler à son souvenir, se souvenir de, se rappeler : τι, ESCHL. <i>Pers. 780 ;</i> SOPH. <i>Ph. 121 ;</i> HDT. <i>1, 36 ;</i> XÉN. <i>Mem. 2, 7, 7, etc. ; postér</i>. τινός, PLUT. <i>Oth. 1 ;</i> LUC. <i>D. mar. 12, 2, etc</i>. qqe ch. ; <i>avec l’inf</i>. AR. <i>Eccl. 264,</i> se souvenir de ; <i>avec ὅτι,</i> PLAT. <i>Rsp. 480</i> a ; <i>ou</i> ἡνίκα, SOPH. <i>Aj. 1273, ou</i> εἰ, DÉM. <i>12, 15,</i> se souvenir que, <i>etc. ; d’où au pass</i>. être conservé dans le souvenir, rester dans la mémoire, THC. <i>1, 23 ;</i> XÉN. <i>Mem. 4, 8, 2 ;</i><br><b>      2</b> rappeler le souvenir de, faire mention de, <i>gén</i>. PLUT. <i>Them. 32, M. 631</i> a ; ATH. <i>101</i> a ; τὶ μν. τινί, SOCR. <i>Ep. p. 66, 27,</i> mentionner qqe ch. à qqn ; <i>au pass</i>. être transmis par le souvenir (des hommes), XÉN. <i>Hell. 4, 8, 4 ;</i> EUR. <i>Her. 334 ;</i> PLAT. <i>Leg. 723</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. ἐμνημόνευκα, PAUS. <i>3, 20, 6 ;</i> ORIB. <i>1, 352 ; irrég</i>. μνημόνευκα, ORIB. <i>p. 11 Mai. Fut. moy. au sens pass. 3 sg</i>. μνημονεύσεται, EUR. <i>Her. 334 ; ao</i>. ἐμνημονευσάμην, GAL. <i>15, 20</i>.<br><span><b>Étym</b>. μνήμων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μνημονευω - μνημονεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 21 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n<li>Actes (2)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (3)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G3422":"<h1>mnemosunon</h1>\n<p>Strong n° 3422 <i>Prononciation [mnay-mos'-oo-non]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un mémorial (par lequel la mémoire est préservée), un souvenir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>μνημόσυνος, η, ον</b> <span>[ῠ]</span> qu’on rappelle à la mémoire <i>ou</i> dont on conserve le souvenir, AR. <i>Vesp. 538 ; subst</i>. τὸ μνημόσυνον :<br><b>      1</b> ce qui rappelle un souvenir, monument, HDT. <i>2, 135 ; 4, 166 ;</i> THC. <i>5, 11 ; plur. au sens du sg</i>. HDT. <i>2, 148, etc. ;</i> εἰς μνημόσυνόν τινος, NT. <i>Matth. 26, 13 ; Marc. 14, 9,</i> en souvenir de qqn ;<br><b>      2</b> la mémoire, NT. <i>Ap. 10, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. μναμόσυνον <span>[ᾱ]</span> ANTH. <i>12, 68</i>.<br><span><b>Étym</b>. μνήμων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μνημοσυνον - μνημόσυνον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3423":"<h1>mnesteuo</h1>\n<p>Strong n° 3423 <i>Prononciation [mnace-tyoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire la cour à une fille et la demander en mariage</li>\n<li>être promise en mariage, être fiancée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μνηστεύω</b> <span>(<i>f</i>. μνηστεύσω, <i>ao</i>. ἐμνήστευσα, <i>pf</i>. μεμνήστευκα)</span><br><b>   I</b> penser à, désirer, <i>d’où :</i><br><b>      1</b> rechercher une femme en mariage, EUR. <i>Alc. 720, I.A. 841 ; avec l’inf. :</i> γυναῖκα λαϐεῖν, XÉN. <i>Hell. 6, 4, 37,</i> prétendre à obtenir pour femme ; <i>au pass</i>. être recherchée <i>ou</i> se faire rechercher en mariage, EUR. <i>I.T. 208 ;</i> ISOCR. <i>215</i> e ; NT. <i>Matth. 1, 18 ; Luc. 1, 27 ; p. suite,</i> épouser une femme, THGN. <i>1112 ;</i> THCR. <i>Idyl. 18, 6 ; 22, 155 ;</i> μν. γάμον, PLAT. <i>Leg. 773</i> b, contracter un mariage ;<br><b>      2</b> rechercher, ambitionner, briguer, <i>en gén. acc</i>. ISOCR. <i>162</i> a ; JUL. <i>Ep. 28 ;</i><br><b>   II</b> donner en mariage, fiancer : τινί τινα, APD. <i>2, 5, 5,</i> une jeune fille à qqn ; γάμον τινί, A. RH. <i>2, 511 ; ou simpl</i>. γάμον, APD. <i>2, 5, 12 ; ou</i> γάμους, EUR. <i>I.A. 847,</i> consentir à un mariage ;<br><b><i>Moy.</i></b> rechercher pour soi, briguer : μοναρχίαν, PLUT. <i>Cæs. 58,</i> le pouvoir absolu, la monarchie ; <i>avec un inf</i>. ambitionner de, PLUT. <i>Cæs. 28</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. inf. dor</i>. μναστεύειν, THCR. <i>Idyl. 22, 155 Mein. ; impf. poét</i>. μνήστευον, IL. <i>14, 200 ; ao. part. dor</i>. μναστεύσας, THCR. <i>Idyl. 18, 6. Pass. ao. dor</i>. ἐμναστεύθην, EUR. <i>I.T. 208 ; pf. (sans redoubl</i>.) ἐμνήστευμαι, NT. <i>Luc. 1, 27 ; 2, 5</i>.<br><span><b>Étym</b>. μνηστής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μνηστευω - μνηστεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G3424":"<h1>mogilalos</h1>\n<p>Strong n° 3424 <i>Prononciation [mog-il-al'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parler avec difficulté, muet</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μογι·λάλος, ος, ον</b> <span>[ῐᾰ]</span><br><b>      1</b> qui parle difficilement, qui bégaie, AÉT. <i>8, 38 ;</i><br><b>      2</b> muet, SPT. <i>Esaï. 35, 6 ;</i> NT. <i>Marc. 7, 32</i>.<br><span><b>Étym</b>. μόγις, λαλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μογιλαλος - μογιλάλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G3425":"<h1>mogis</h1>\n<p>Strong n° 3425 <i>Prononciation [mog'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>durement, avec difficulté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μόγις</b> <span>[ῐ]</span> <i>adv. :</i><br><b>      1</b> avec peine, IL. <i>9, 355 ; 21, 417 ; 22, 412 ;</i> OD. <i>3, 119 ; 19, 189 ;</i> ESCHL. <i>Pr. 131 ;</i> HDT. <i>1, 116 ;</i> PLAT. <i>Rsp. 342</i> c ; πάνυ μ. PLAT. <i>Prot. 360</i> d, tout à fait avec peine ; μ. πως, PLAT. <i>Charm. 155</i> e, avec qqe peine ;<br><b>      2</b> à peine, ARSTT. <i>Nic. 4, 3, 26</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Par exc</i>. <span>[ῑ]</span> <i>à l’arsis,</i> IL. <i>22, 412</i>.<br><span><b>Étym</b>. μόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μογις - μόγις</font>\n<br><br>vient du mot primaire 'mogos' (peiner)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3426":"<h1>modios</h1>\n<p>Strong n° 3426 <i>Prononciation [mod'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mesure de volume pour matière sèche d'environ 9 litres</li>\n<li>meuble où l'on met en réserve le gain</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μόδιος, ου (ὁ) :<br>      1</b> mesure pour les grains, boisseau de 16 setiers, le tiers d’une amphore (25 litres environ) DIN. <i>95, 37 ;</i> JUL. <i>369</i> b ;<br><b>      2</b> mesure de longueur de 200 ὀργυιαί environ, HÉRON.<br><span><b>Étym</b>. <i>cf. lat</i>. modius.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοδιος - μόδιος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3427":"<h1>moi</h1>\n<p>Strong n° 3427 <i>Prononciation [moy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>Je, moi, me</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μοί</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοι - μοι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n239 fois dans 226 versets de 18 livres bibliques (NT)\n<ul>\n<li>Matthieu (30)</li>\n<li>Marc (9)</li>\n<li>Luc (28)</li>\n<li>Jean (41)</li>\n<li>Actes (36)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (15)</li>\n<li>2 Corinthiens (11)</li>\n<li>Galates (5)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (7)</li>\n<li>Colossiens (2)</li>\n<li>2 Timothée (7)</li>\n<li>Philémon (3)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (25)</li>\n</ul>\n</td></tr>\n</table>","G3428":"<h1>moichalis</h1>\n<p>Strong n° 3428 <i>Prononciation [moy-khal-is']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>intention ou acte adultère, une femme adultère</li>\n<li>l'alliance intime de Dieu avec le peuple d'Israël étant comme un mariage, ceux qui rechutent dans l'idolâtrie sont considérés comme commettant l'adultère ou se livrant à la prostitution\n<ol type=\"a\">\n<li>fig. équiv. à être infidèle à Dieu, impur, apostat</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μοιχαλίς, ίδος (ἡ)</b> <span>[ᾰῐδ]</span><br><b>      1</b> femme adultère, NT. <i>Matth. 12, 39 ; 16, 4 ; Jac. 4, 4, etc. ;</i><br><b>      2</b> le crime d’adultère, NT. <i>2Petr. 2, 14</i>.<br><span><b>Étym</b>. μοιχός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοιχαλις - μοιχαλίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Romains (2)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3429":"<h1>moichao</h1>\n<p>Strong n° 3429 <i>Prononciation [moy-khah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avoir une relation illicite (avec une autre femme ou un homme), commettre un adultère avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μοιχάω-ῶ :<br>      1</b> séduire une femme mariée, <i>d’où, fig</i>. obtenir les faveurs de, <i>acc</i>. XÉN. <i>Hell. 1, 6, 15 ;</i><br><b>      2</b> <i>p. ext</i>. corrompre, altérer, <i>acc</i>. EL. <i>N.A. 7, 39 ;</i><br><b><i>Moy.</i></b> commettre un adultère, <i>en parl. de l’homme,</i> NT. <i>Matth. 5, 32 ; 19, 9 ; ou de la femme,</i> NT. <i>Marc. 10, 13</i>.<br><span><b>Étym</b>. μοιχός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοιχαω - μοιχάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G3430":"<h1>moicheia</h1>\n<p>Strong n° 3430 <i>Prononciation [moy-khi'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>péché d'adultère</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μοιχεία, ας (ἡ)</b> crime d’adultère, PLUT. <i>M. 475</i> b ; <i>au plur</i>. PLAT. <i>Leg. 839</i> a, <i>Rsp. 443</i> a, <i>etc. ; fig. en parl. de l’inclination à l’idolâtrie,</i> CLÉM. <i>687</i>.<br><span><b>Étym</b>. μοιχός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοιχεα - μοιχεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3431":"<h1>moicheuo</h1>\n<p>Strong n° 3431 <i>Prononciation [moy-khyoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>commettre un adultère\n<ol type=\"a\">\n<li>être un adultère</li>\n<li>avoir une relation illicite avec une autre femme</li>\n<li>d'une épouse : être une femme adultère, être débauchée</li>\n<li>idiome Hébreu : mot utilisé pour ceux qui sont amenés à l'idolâtrie suite à la sollicitation d'une femme, ceux qui mangent les choses consacrées aux idoles</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μοιχεύω<br>   I <i>intr.</i></b> commettre un adultère, entretenir une liaison adultère, XÉN. <i>Cyr. 1, 22 ;</i> AR. <i>Av. 793 ;</i> PLUT. <i>M. 519</i> e ; NT. <i>Luc. 16, 18 ;</i><br><b>   II <i>tr</i>.<br>      1</b> corrompre une femme mariée, <i>acc</i>. AR. <i>Av. 559 ;</i> PLAT. <i>Rsp. 360</i> b ; <i>au pass. en parl. d’une femme,</i> se laisser séduire, AR. <i>Pax 985 ;</i> DÉM. <i>1383, 2 ;</i> ὑπό τινος, LUC. <i>D. mar. 12, 1 ;</i> ATH. <i>578</i> f ; τινι, ARSTT. <i>H.A. 7, 6,</i> par qqn ;<br><b>      2</b> altérer, entacher de fraude, A. TAT. <i>4, 8 ;</i><br><b>      3</b> <i>t. eccl</i>. adorer des idoles, SPT. <i>Jer. 3, 9</i>.<br><span><b>Étym</b>. μοιχός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοιχευω - μοιχεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 11 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (2)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Romains (4)</li>\n<li>Jacques (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3432":"<h1>moichos</h1>\n<p>Strong n° 3432 <i>Prononciation [moy-khos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un adultère</li>\n<li>métaph. celui qui est infidèle envers Dieu, un impie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μοιχός, οῦ (ὁ) :<br>      1</b> homme adultère, AR. <i>Pl. 168 ;</i> PLUT. <i>M. 470</i> a ;<br><b>      2</b> action de porter les cheveux ras, selon le mode de châtiment imposé aux adultères, AR. <i>Ach. 849</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *h₃meiǵ<sup>h</sup>-, uriner.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοιχος - μοιχός</font>\n<br><br>peut-être un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G3433":"<h1>molis</h1>\n<p>Strong n° 3433 <i>Prononciation [mol'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avec difficulté, à peine</li>\n<li>non facilement, c.à.d. rarement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μόλις</b> <span>[ῐ]</span> <i>adv</i>., avec peine, difficilement, ATT. ; οὐ μόλις, ESCHL. <i>Ag. 1082 ;</i> EUR. <i>Hel. 334,</i> sans peine.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μολις - μόλις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (4)</li>\n<li>Romains (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3434":"<h1>Moloch</h1>\n<p>Strong n° 3434 <i>Prononciation [mol-okh']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Moloch (Angl. Molech) = « roi »\n<ol><li>le nom du dieu, idole des Ammonites, à qui des victimes humaines étaient offertes en sacrifice, particulièrement de jeunes enfants. Son image était une statue creuse en bronze, avec une tête de bœuf, et des bras humains. Un grand feu était allumé à l'intérieur, et les enfants étaient placés sur ses bras pour être lentement brûlés, tandis que les sacrificateurs battaient du tambour pour que les parents n'entendent pas les cris.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μολοχ</font> &lt; מלך - <font face=\"Georgia\">Μολόχ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3435":"<h1>moluno</h1>\n<p>Strong n° 3435 <i>Prononciation [mol-oo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>polluer, tacher, contaminer, souiller\n<ol type=\"a\">\n<li>utilisé dans le N.T. pour ceux qui ne se sont pas gardés purs de la souillure du péché, qui se sont souillés par la fornication et l'adultère</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μολύνω</b> <span>[ῡ]</span> <span>(<i>f</i>. υνῶ <span>[ῠ]</span>, <i>ao</i>. ἐμόλυνα, <i>pf</i>. μεμόλυγκα ; <i>pf. pass</i>. μεμόλυμμαι <i>ou</i> μεμόλυσμαι)</span><br><b>      1</b> salir, souiller, tacher, <i>acc</i>. NT. <i>Apoc. 3, 4 ;</i> ἀλεύρῳ, SOTAD. (ATH. <i>293</i> d) saupoudrer de farine ; τῷ πηλῷ, ARSTT. <i>H.A. 6, 18,</i> souiller de boue ; <i>au pass</i>. être sali, se salir : μολύνεσθαι ἐν, <i>etc</i>. PLAT. <i>Rsp. 535</i> e, se vautrer dans ; μ. ὑπὸ ὄψου, MUSON. (STOB. <i>Fl. 18, 38, vol. 1, p. 298, l. 11</i>) se gorger de qqe plat ; <i>fig</i>. τινι, ISOCR. <i>98</i> c, se salir par le contact <i>ou</i> la fréquentation de qqn ; <i>particul</i>. souiller, polluer, <i>en un sens obscène, acc</i>. AR. <i>Eq. 1286, Pl. 310 ;</i><br><b>      2</b> faire rôtir de la viande à la surface, braiser de la viande, ARSTT. <i>G.A. 4, 1, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. μεμόλυγκα, GRAMM. (<i>Cram. t. 4, p. 197) ; pf. pass</i>. μεμόλυμμαι, SPT. <i>1Esdr. 8, 80 ; Esaï. 65, 4 ; 2 Macc. 14, 3 ; part</i>. μεμολυμμένος, ARSTT. <i>H.A. 10 fin ; ou</i> μεμολυσμένος, EPICT. <i>Ench. 33, 6</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μολυνω - μολύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>, « teindre, teinter, souiller », diffère de , « tacher, contaminer, souiller », non seulement dans un sens primaire ou secondaire, mais aussi dans les circonstances, car il peut être utilisé en bonne part, tandis que  n'a aucune utilisation digne.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G3436":"<h1>molusmos</h1>\n<p>Strong n° 3436 <i>Prononciation [mol-oos-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souillure, l'action par laquelle une chose est souillée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μολυσμός, οῦ (ὁ)</b> tache, souillure, PLUT. <i>M. 779</i> c ; NT. <i>2Cor. 7, 1</i>.<br><span><b>Étym</b>. μολύνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μολυσμος - μολυσμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3437":"<h1>momphe</h1>\n<p>Strong n° 3437 <i>Prononciation [mom-fay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>blâme, reproche</li>\n<li>avoir une plainte à porter contre quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μομφή, ῆς (ἡ)</b> blâme, reproche, plainte, grief, PD. <i>N. 8, 39 ;</i> ESCHL. <i>Sept. 1010 ;</i> EUR. <i>Ion 885 ;</i> PLAT. <i>Ep. 323</i> b ; <i>au plur</i>. EUR. <i>Ph. 785 ;</i> LYC. <i>59, 450 ;</i> μομφὴν ἔχειν τινί, PD. <i>I. 3, 54 ; ou</i> τινός, SOPH. <i>Aj. 180,</i> avoir un grief contre qqn <i>ou</i> qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. μομφά, PD. <i>ll. cc. ;</i> EUR. <i>Ion 885</i>.<br><span><b>Étym</b>. μέμφομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μομφη - μομφή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3438":"<h1>mone</h1>\n<p>Strong n° 3438 <i>Prononciation [mon-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une demeure, une habitation, un logis, un domicile</li>\n<li>faire sa demeure</li>\n<li>métaph. du saint Esprit demeurant dans les croyants</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μονή, ῆς (ἡ) :<br>   I</b> action de s’arrêter, <i>d’où :</i><br><b>      1</b> halte, séjour, HDT. <i>1, 94 ;</i> XÉN. <i>An. 5, 1, 5 ;</i> PLUT. <i>M. 1063</i> d ;<br><b>      2</b> retard, lenteur, THC. <i>1, 131 ; particul</i>. repos, pause, PLUT. <i>M. 747</i> c ;<br><b>   II</b> lieu où l’on réside :<br><b>      1</b> auberge, hôtellerie, PAUS. <i>10, 31, 7 ; d’où en gén</i>. logement, NT. <i>Joh. 14, 2 ;</i><br><b>      2</b> monastère, NAZ. <i>3, 220 Migne</i>.<br><span><b>Étym</b>. μένω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μονη - μονή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G3439":"<h1>monogenes</h1>\n<p>Strong n° 3439 <i>Prononciation [mon-og-en-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>seul de son espèce, unique\n<ol type=\"a\">\n<li>utilisé pour un fils ou une fille unique (en relation avec leurs parents)</li>\n<li>utilisé pour Christ, dénote le fils unique de Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μονο·γενής, ής, ές :<br>      1</b> engendré seul, unique enfant, HÉS. <i>O. 374 ; Th. 426, 448 ;</i> ESCHL. <i>Ag. 898 ;</i> HDT. <i>7, 221 ;</i> PLAT. <i>Criti. 113</i> d, <i>Leg. 691</i> d ;<br><b>      2</b> issu d’une même race, parent par le sang, EUR. <i>Hel. 1685 ;</i><br><b>      3</b> <i>t. de gramm</i>. qui n’a qu’un genre, DRAC. <i>30, 15 ;</i> DYSC. <i>Adv. 615, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et ion</i>. μουνογενής, HÉS. HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. μ. γένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μονογενης - μονογενής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Jean (4)</li>\n<li>Hébreux (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3440":"<h1>monon</h1>\n<p>Strong n° 3440 <i>Prononciation [mon'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>seulement, seul, ne ...que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>μονον·ού</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μονον - μόνον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n66 fois dans 66 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Jean (5)</li>\n<li>Actes (8)</li>\n<li>Romains (11)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (5)</li>\n<li>Galates (6)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (4)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G3441":"<h1>monos</h1>\n<p>Strong n° 3441 <i>Prononciation [mon'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>seul (sans un compagnon), abandonné, sans secours, simplement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μόνος, η, ον :<br>A</b> <i>adj</i>. seul, <i>càd. :</i><br><b>   I</b> seul, unique, IL. <i>2, 212 ; 9, 477, etc. ;</i> OD. <i>16, 118, etc. ;</i> HÉS. <i>Th. 143, O. 96 ; joint à</i> εἷς, μία, ἕν, OD. <i>23, 227 ;</i> HDT. <i>1, 38 ; à</i> πρῶτος, PHALAR. <i>Ep. 2, p. 6, 26 ; avec le gén</i>. seul d’entre, <i>etc</i>. ESCHL. (AR. <i>Ran. 1392), etc. ;</i><br><b>   II</b> solitaire, isolé, ESCHL. <i>Suppl. 748 ;</i> SOPH. <i>Ph. 172 ; avec un gén</i>. isolé de, privé de, SOPH. <i>Aj. 510 ;</i><br><b>B</b> <i>adv. :</i><br><b>   I</b> μόνον :<br><b>      1</b> seulement, ATT. ; οὐ μόνον… ἀλλά, ATT. non seulement… mais encore ; οὐ μόνον, <i>au sens de</i> οὐ μόνον οὐ, non seulement… ne pas, XÉN. <i>Cyr. 8, 8, 16 et 17 ; Hell. 3, 2, 21 ;</i> DÉM. <i>497, 13 ;</i> οὐ μόνον γε… ἀλλὰ καί, XÉN. <i>Cyr. 1, 6, 17,</i> non seulement certes…, mais encore ; <i>cf</i>. PLAT. <i>Leg. 752</i> a ; μόνον οὐ, AR. <i>Vesp. 516, Eccl. 538 ;</i> POL. <i>3, 64, 5, etc. ;</i> μονονουχί, LUC. <i>Tim. 12 ;</i> μόνον δ' οὐχί, POL. <i>3, 64, 4,</i> peu s’en faut que, presque ;<br><b>      2</b> seulement, du moins, <i>avec l’opt</i>. ESCHL. <i>Ch. 244 ; avec l’impér</i>. ESCHL. <i>Suppl. 1012 ;</i> μόνον μή, XÉN. <i>Conv. 8, 6 ;</i> μὴ μόνον, EUR. <i>Cycl. 219,</i> que seulement… ne, que du moins… ne, pourvu que… ne, à moins que… ;<br><b>   II</b> <i>acc. pl. fém</i>. μόνας <i>dans la loc</i>. κατὰ μόνας, à soi seul, séparément, THC. <i>1, 32 et 37 ;</i> XÉN. <i>Mem. 3, 7, 4 ;</i> PLAT. <i>Leg. 942</i> a, <i>etc</i>.<br><span>•<i> Sup</i>. μονώτατος, AR. <i>Pl. 182, Eq. 352 ;</i> THCR. <i>Idyl. 15, 137</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion. épq. et poét</i>. μοῦνος, <i>seule forme dans Hom. ; alternant avec μόνος dans</i> SOPH. <i>O.R. 1418 ; dor</i>. μῶνος, THCR. <i>Idyl. 20, 45 ; fém. éol</i>. μόνα, SAPPH. <i>52 Bgk</i>.<br><span><b>Étym</b>. <i>p</i>. *μόνϝος, <i>p.-ê. indo-europ</i>. *mon-uo-, <i>de la</i> R. *men- petit, <i>cf</i>. μανός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μονος - μόνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 46 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (3)</li>\n<li>Luc (8)</li>\n<li>Jean (10)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>2 Jean (1)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G3442":"<h1>monophthalmos</h1>\n<p>Strong n° 3442 <i>Prononciation [mon-of'-thal-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>privé d'un œil, n'ayant qu'un œil, borgne</li>\n<li>rester seul</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μον·όφθαλμος, ος, ον</b>, qui n’a qu’un œil, STR. <i>70</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. μουνόφθαλμος, HDT. <i>3, 116 ; 4, 13 et 27, etc</i>.<br><span><b>Étym</b>. μ. ὀφθαλμός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μονοφθαλμος - μονόφθαλμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n<br2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G3443":"<h1>monoo</h1>\n<p>Strong n° 3443 <i>Prononciation [mon-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être rendu seul, solitaire</li>\n<li>laisser seul, abandonner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μονόω-ῶ :<br>      1</b> réduire à un, OD. <i>16, 117 ;</i><br><b>      2</b> isoler, laisser seul, POL. <i>5, 16, 10 ; d’où</i> tenir séparé des autres, ANTH. <i>9, 451 ; au pass</i>. être isolé, IL. <i>11, 470 ;</i> OD. <i>15, 385 ;</i> THC. <i>2, 81, etc. ;</i> PLAT. <i>Tim. 59</i> e, <i>etc. ;</i> τινος, HDT. <i>1, 102, etc. ;</i> XÉN. <i>Cyn. 9, 9 ;</i> PLAT. <i>Leg. 710</i> b, <i>etc. ;</i> ἔκ τινος, PLAT. <i>Ax. 370</i> d, être dégagé de qqe ch. (d’un lien, <i>etc</i>.) ; ἀπό τινος, EUR. <i>I.A. 669,</i> être séparé de qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. μουνόω, HDT. <i>1, 102, 116 ; 4, 113, etc</i>.<br><span><b>Étym</b>. μόνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μονοω - μονόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3444":"<h1>morphe</h1>\n<p>Strong n° 3444 <i>Prononciation [mor-fay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la forme par laquelle une personne ou une chose frappe la vision</li>\n<li>apparence externe</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μορφή, ῆς (ἡ)</b> forme, <i>d’où :</i><br><b>      1</b> forme du corps, figure, extérieur, <i>en parl. des hommes,</i> ESCHL. <i>Pr. 21, etc. ;</i> SOPH. <i>El. 1159, etc. ; ou des dieux,</i> OD. <i>8, 170 ;</i> XÉN. <i>Mem. 4, 3, 13 ; joint à</i> εἶδος, A. RH. <i>4, 1193 ; en parl. des plantes,</i> TH. <i>H.P. 1, 1, 11, etc. ; 3, 10, 4, etc. ; au plur. au sens du sg</i>. ORPH. <i>Arg. 879 ; particul. en parl. de la taille,</i> PD. <i>I. 3, 74 ; en b. part,</i> beauté, PD. <i>O. 6, 128, etc. ;</i><br><b>      2</b> forme, apparence, SOPH. <i>El. 199, Tr. 699 ; p. opp. à</i> εἶδος « forme réelle », PLAT. <i>Rsp. 380</i> d ; <i>en parl. de songes, de fantômes,</i> ESCHL. <i>Pr. 449 ;</i> POÈT. (ATH. <i>491</i> a) ; CALL. <i>Ep. 68, 2 ;</i><br><b>      3</b> forme, sorte, espèce, EUR. <i>Ion 382, 1067 ;</i> PLAT. <i>Rsp. 397</i> c ;<br><b>      4</b> forme artificielle, gesticulation, mines, DH. <i>10, 15 ;</i><br><b>      5</b> <i>p. ext. dans les écriv. ecclés</i>. μ. θεοῦ, NT. <i>Phil. 2, 6 ;</i> NYSS. <i>2, 566, etc</i>. la nature <i>ou</i> l’essence de Dieu revêtue en qqe sorte de ses attributs, la Gloire et la Majesté.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. μορφά, PD. <i>ll. cc</i>.<br><span><b>Étym</b>. <i>cf. lat</i>. forma.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μορφη - μορφή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Philippiens (2)</li>\n</ul>\n</td></tr>\n</table>","G3445":"<h1>morphoo</h1>\n<p>Strong n° 3445 <i>Prononciation [mor-fo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>former, être formé, prendre forme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μορφόω-ῶ</b>, donner une forme à, figurer, représenter, <i>acc</i>. ARAT. <i>374 ;</i> ANTH. <i>1, 33 ; au pass</i>. prendre une forme, TH. <i>C.P. 5, 6, 7 ;</i> PLUT. <i>M. 1013</i> c ; NT. <i>Gal. 4, 19</i>.<br><span><b>Étym</b>. μορφή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μορφοω - μορφόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G3446":"<h1>morphosis</h1>\n<p>Strong n° 3446 <i>Prononciation [mor'-fo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une forme</li>\n<li>former\n<ol type=\"a\">\n<li>la forme simple, l'apparence</li>\n<li>la forme traduisant une chose ou exprimant réellement un fait, la règle</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μόρφωσις, εως (ἡ) :<br>      1</b> action de donner une forme à, TH. <i>C.P. 3, 7, 4 ;</i><br><b>      2</b> <i>d’où</i> forme, figure, extérieur, NT. <i>Rom. 2, 20 ; 2Tim. 3, 5</i>.<br><span><b>Étym</b>. μορφόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μορφωσις - μόρφωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3447":"<h1>moschopoieo</h1>\n<p>Strong n° 3447 <i>Prononciation [mos-khop-oy-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire (l'image, la statue) d'un veau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μοσχο·ποιέω-ῶ</b>, fabriquer l’image d’un veau (pour l’adorer) NT. <i>Ap. 7, 41</i>.<br><span><b>Étym</b>. μόσχος, ποιέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοσχοποιεω - μοσχοποιέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3448":"<h1>moschos</h1>\n<p>Strong n° 3448 <i>Prononciation [mos'-khos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une pousse tendre et juteuse\n<ol type=\"a\">\n<li>un rejeton, de plante ou d'arbre</li>\n</ol>\n</li>\n<li>descendant\n<ol type=\"a\">\n<li>de l'homme: garçon ou jeune fille, spéc. frais et délicat</li>\n<li>d'animaux : un jeune</li>\n</ol>\n</li>\n<li>un veau, un bouvillon, une génisse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μόσχος, ου (ὁ, ἡ) :<br>   I</b> rejeton d’une plante, jeune pousse, IL. <i>11, 105 ; particul</i>. marcotte, ARSTT. <i>H.A. 9, 40 ;</i> TH. <i>H.P. 4, 7, 8, etc. ; C.P. 5, 9, 1 ;</i> NIC. <i>Th. 72 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> rejeton d’un homme, jeune garçon, jeune fille, EUR. <i>Hec. 205, 526 ; Andr. 711 (cf</i>. ἔρνος ὄζος) ;<br><b>      2</b> petit d’un animal, d’un oiseau, ACHÆ. (EL. <i>N.A. 7, 47) ; particul</i>. veau, génisse, EUR. <i>Bacch. 678 ;</i> PLAT. <i>Crat. 393</i> c, <i>Ap. 20</i> a ; ARSTT. <i>H.A. 5, 14 ;</i> NIC. <i>Th. 552 ;</i> NT. <i>Luc. 15, 23 ; Hebr. 9, 19 ; p. ext. en parl. du bœuf Apis,</i> HDT. <i>3, 28 ; ou de la gazelle qui donne le musc,</i> AÉT. <i>1, p. 9</i> b, <i>43 ; d’où</i> odeur musquée, odeur <i>en gén</i>. DIOSC. <i>Eup. 1, 154, p. 174</i>.<br><span><b>Étym</b>. <i>cf. sscr</i>. uksh-an « bœuf », <i>lat</i>. vacc-a.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοσχος - μόσχος</font>\n<br><br>probablement renforcement de 'oschos' (rejeton)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3449":"<h1>mochthos</h1>\n<p>Strong n° 3449 <i>Prononciation [mokh'-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un travail dur et difficile, dur labeur, privation, détresse, peine, fatigue</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μόχθος, ου (ὁ) :<br>      1</b> peine, travail, fatigue, <i>en parl. de la fatigue du corps ou de celle de l’esprit,</i> HÉS. <i>Sc. 306 ;</i> PD. <i>O. 11, 97 ; P. 2, 30, etc. ;</i> XÉN. <i>Conv. 2, 4 ;</i> NT. <i>1Thess. 2, 9 ;</i><br><b>      2</b> <i>p. suite,</i> souffrance, douleur, TRAG. ;<br><b>      3</b> <i>p. ext</i>. produit d’un travail, œuvre d’art, A. PL. <i>178, 2</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μοχθος - μόχθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – donne la prééminence à l'effort (travail demandant de la force)\n<br><br> – se réfère à la fatigue\n<br><br> – se réfère à la peine et à la privation (principalement en exposé poétique)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G3450":"<h1>mou</h1>\n<p>Strong n° 3450 <i>Prononciation [moo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>Je, moi, mon, de moi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μοῦ</b>, <i>gén. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μου - μου</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n579 fois dans 466 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (89)</li>\n<li>Marc (42)</li>\n<li>Luc (92)</li>\n<li>Jean (106)</li>\n<li>Actes (49)</li>\n<li>Romains (37)</li>\n<li>1 Corinthiens (30)</li>\n<li>2 Corinthiens (12)</li>\n<li>Galates (8)</li>\n<li>Ephésiens (5)</li>\n<li>Philippiens (24)</li>\n<li>Colossiens (5)</li>\n<li>2 Timothée (8)</li>\n<li>Philémon (6)</li>\n<li>Hébreux (18)</li>\n<li>Jacques (14)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (3)</li>\n<li>Apocalypse (28)</li>\n</ul>\n</td></tr>\n</table>","G3451":"<h1>mousikos</h1>\n<p>Strong n° 3451 <i>Prononciation [moo-sik-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dévoué et habile dans les arts sacrés des muses</li>\n<li>accomplis dans les arts libéraux</li>\n<li>spécifiquement, habile en musique</li>\n<li>joueur d'un instrument de musique</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μουσικός, ή, όν :<br>A</b> <i>adj. :</i><br><b>   I</b> qui concerne les Muses, <i>p. suite,</i> la poésie <i>ou</i> les arts, <i>particul</i>. la musique : μ. ἀκούσματα, PLAT. <i>Ax. 371</i> d, concerts ; θέαι μ. PLUT. <i>Fab. 4,</i> auditions musicales ;<br><b>   II</b> qui cultive la musique, musicien, chanteur, XÉN. <i>Cyr. 1, 6, 38 ;</i> PLAT. <i>Leg. 802</i> b, <i>etc. ;</i> ARSTT. <i>Nic. 10, 4 ;</i><br><b>   III</b> <i>p. suite :</i><br><b>      1</b> instruit, AR. <i>Vesp. 1244 ; d’où</i> habile à, <i>inf</i>. EUR. <i>Hipp. 989 ;</i><br><b>      2</b> délicat, <i>en parl. d’aliments,</i> PLUT. <i>M. 127</i> b ;<br><b>B</b> <i>subst. :</i><br><b>   I</b> ἡ μουσική (<i>s.-e</i>. τέχνη <i>ou</i> ἐπιστήμη) :<br><b>      1</b> la musique, HDT. <i>3, 131 ;</i> XÉN. <i>Lac. 2, 1 ;</i> ARSTT. <i>Pol. 8, 3 ;</i> PLUT. <i>M. 474</i> a, <i>etc. ;</i><br><b>      2</b> instruction, <i>en gén</i>. PD. <i>O. 1, 15 ;</i> PLAT. <i>Rsp. 376</i> e, <i>etc. ;</i><br><b>      3</b> <i>p. suite,</i> habileté, dextérité, EUR. <i>Suppl. 906 ;</i><br><b>   II</b> τὰ μουσικά, la musique, XÉN. <i>Cyr. 1, 6, 38 ;</i> PLAT. <i>Rsp. 403</i> c, <i>etc</i>.<br><span>•<i> Cp</i>. μουσικώτερος, EUR. <i>Hipp. 989 ;</i> ATH. <i>176</i> e ; <i>sup</i>. -ώτατος, MACH. (ATH. <i>664</i> b) ; PLUT. <i>Lyc. 21</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor. fém. subst</i>. μουσικά, PD. <i>l. c</i>.<br><span><b>Étym</b>. μοῦσα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μουσικος - μουσικός</font>\n<br><br>vient de 'Mousa' (une Muse)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Substantif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3452":"<h1>muelos</h1>\n<p>Strong n° 3452 <i>Prononciation [moo-el-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>moelle</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυελός, οῦ (ὁ)</b> <span>[ῡ, HOM. ; ῠ, ATT.]</span> moelle, IL. <i>20, 482 ; 22, 501 ;</i> ESCHL. <i>Ag. 77 ;</i> T. LOCR. <i>100</i> b ; PLAT. <i>Tim. 74</i> a, <i>etc. ;</i> moelle d’un arbre, TH. <i>H.P. 1, 2, 6 ;</i> ANTH. <i>6, 232, etc. ; par ext</i>. toute substance nutritive <i>ou</i> fortifiante, OD. <i>2, 290 ; 20, 108 ; fig</i>. ville qui fait la force <i>ou</i> la grandeur d’un pays, THCR. <i>Idyl. 28, 18</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. μύελος <span>[ῡ]</span> THCR. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυελος - μυελός</font>\n<br><br>peut-être un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3453":"<h1>mueo</h1>\n<p>Strong n° 3453 <i>Prononciation [moo-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>initié dans les mystères</li>\n<li>enseigner pleinement, instruire\n<ol type=\"a\">\n<li>accoutumer quelqu'un à une chose</li>\n<li>donner à quelqu'un une connaissance intime d'une chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἐμύησα, <i>pf</i>. μεμύηκα)</span><br><b>      1</b> initier aux mystères, PLAT. <i>Conv. 210</i> a ; DÉM. <i>1351, 26 ;</i> PLUT. <i>M. 607</i> b ; <i>au pass. abs</i>. HDT. <i>8, 65 ;</i> AR. <i>Ran. 456, Pax 278, etc. ;</i> LUC. <i>Scyth. 8 ; avec un rég</i>. μυεῖσθαι τὰ μεγάλα (<i>s.-e</i>. μυστήρια) AR. <i>Pl. 846,</i> être initié aux grands mystères ; <i>cf</i>. HDT. <i>2, 51 ; qqf. avec le gén</i>. μυεῖσθαι τῆς Ἀφροδίτης, HLD. <i>1, 17,</i> être initié aux mystères d’Aphrodite ; <i>ou en gén</i>. μ. τι, PLUT. <i>M. 795</i> e, être initié à qqe ch. ;<br><b>      2</b> <i>par ext</i>. initier à une science, à un art, <i>etc., d’où</i> enseigner, instruire, <i>acc</i>. ANTH. <i>9, 162 ; au pass</i>. être instruit à, <i>inf</i>. ALCIPHR. <i>2, 4, 21</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. prés. 3 sg. ion</i>. μυέεται, HDT. <i>8, 65 ; fut. moy. au sens pass</i>. μυήσομαι, PHILSTR. <i>V. Ap. 4, 156</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυεω - μυέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3454":"<h1>muthos</h1>\n<p>Strong n° 3454 <i>Prononciation [moo'-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un discours, une parole, des dires</li>\n<li>une narration, une histoire\n<ol type=\"a\">\n<li>une histoire vraie</li>\n<li>une fiction, une fable\n<ol>\n<li>une invention, une affabulation</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μῦθος, ου (ὁ)</b> parole exprimée, <i>d’où :</i><br><b>   I</b> parole, discours, <i>en gén</i>. HOM. ATT. ; <i>joint à</i> ἔπος, OD. <i>11, 561 ; p. opp. à</i> ἔργον, IL. <i>9, 443 ;</i> μῦθον τελεῖν, OD. <i>4, 777,</i> faire une chose dont on a parlé ; <i>particul. :</i><br><b>      1</b> discours public, HÉS. <i>O. 196, etc. ;</i><br><b>      2</b> récit, OD. <i>3, 94 ; 4, 324, etc. ;</i> ESCHL. <i>Pers. 713, etc. ;</i><br><b>      3</b> rumeur, SOPH. <i>Aj. 226, Tr. 67 ;</i><br><b>      4</b> nouvelle, message, SOPH. <i>Ant. 11 ;</i> EUR. <i>Ion 1340 ;</i><br><b>      5</b> dialogue, conversation, entretien, <i>au plur</i>. OD. <i>4, 214, 239 ; 11, 379 ; 23, 301 ;</i> SOPH. <i>O.C. 1164 ; d’où</i> discussion philosophique <i>ou</i> autre, PLAT. <i>Epin. 980</i> a ;<br><b>      6</b> conseil, ordre, prescription, IL. <i>5, 493 ; 7, 358 ; 12, 80 ;</i> OD. <i>1, 358 ;</i><br><b>      7</b> objet du discours <i>ou</i> de la conversation, EUR. <i>El. 346 ;</i><br><b>      8</b> résolution, décision, projet, IL. <i>1, 545 ;</i> OD. <i>3, 140 ; 4, 76 ;</i><br><b>   II</b> <i>après Hom</i>. fable, <i>particul. :</i><br><b>      1</b> légende (<i>p. opp. à</i> λόγος, PD. <i>O. 1, 47, etc. ;</i> HDT. <i>2, 54,</i> récit confirmé par des témoignages), récit non historique, mythe, PLAT. <i>Leg. 636</i> c, <i>Rsp. 330</i> d ;<br><b>      2</b> <i>p. suite,</i> récit fabuleux, conte, <i>p. opp. à</i> ἀληθές, PLAT. <i>Tim. 22</i> c, <i>etc. ;</i> ARSTT. <i>H.A. 6, 31 ;</i> PLUT. <i>M. 348</i> a ; μύθους λέγειν, DÉM. <i>1219, 14,</i> faire des contes, dire des mensonges ;<br><b>      3</b> fable, apologue, AR. <i>Vesp. 566 ;</i> PLAT. <i>Phædr. 60</i> c, <i>1 Alc. 122</i> e ;<br><b>      4</b> jardin auprès de Syracuse, <i>p.-ê. à cause de sa beauté fabuleuse,</i> ATH. <i>542</i> a.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυθος - μῦθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3455":"<h1>mukaomai</h1>\n<p>Strong n° 3455 <i>Prononciation [moo-kah'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>beugler, mugir, comme des bêtes à cornes</li>\n<li>rugir, comme un lion</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυκάομαι-ῶμαι</b> <span>(<i>f</i>. ήσομαι, <i>ao.1</i> ἐμυκησάμην, <i>ao.2 épq</i>. ἔμυκον <span>[ῠ]</span>, <i>pf</i>. μέμυκα <span>[ῡ]</span>)</span> mugir, IL. <i>18, 580 ;</i> OD. <i>10, 413 ;</i> EUR. <i>Bacch. 738 ;</i> PLAT. <i>Rsp. 396</i> b ; <i>p. anal. en parl. de pers</i>. EUR. <i>H.f. 870 ;</i> AR. <i>Ran. 562, Vesp. 1488 ;</i> THCR. <i>Idyl. 22, 75 ; 26, 20 ; ou de choses (du tonnerre,</i> AR. <i>Nub. 292 ; de la mer,</i> PHILSTR. <i>V. Ap. 4, 24 ; d’un fleuve,</i> OPP. <i>C. 4, 166 ; d’un tremblement de terre,</i> PLAT. <i>Rsp. 615</i> e ; ARSTT. <i>Meteor. 2, 8</i>).<br><span><b><span class=\"arrow\"></span></b> <i>Fut. dor</i>. μυκάσομαι <span>[ᾱ]</span>, <i>ao.2 épq</i>. μύκον <span>[ῠ]</span> IL. <i>5, 749 ; 8, 393 ; 12, 460 ; 20, 260. — Act. réc. fut</i>. μυκήσω, SIB. <i>8, 349 ; ao</i>. ἐμύκησα, ANTH. <i>6, 220</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *muH-, mugir ; <i>cf. lat</i>. mūgiō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυκαομαι - μυκάομαι</font>\n<br><br>vient d'un dérivé présumé de 'muzo' (« mugir »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3456":"<h1>mukterizo</h1>\n<p>Strong n° 3456 <i>Prononciation [mook-tay-rid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>« tourner le nez » ou ricaner</li>\n<li>se moquer de, tourner en dérision, mépriser</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυκτηρίζω<br>      1</b> saigner du nez, HPC. <i>1240</i> d ;<br><b>      2</b> se moquer, railler, LYS. (POLL. <i>2, 78</i>) ; SPT. <i>1Esdr. 1, 49, etc. ;</i> NT. <i>Gal. 6, 7 ;</i> SUÉT. <i>Tib. 4 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao. 3 sg. poét</i>. μυκτηρίσατ')</span> APOLLIN. <i>Metaphr. 2 p. 4</i>.<br><span><b>Étym</b>. μυκτήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυκτηριζω - μυκτηρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G3457":"<h1>mulikos</h1>\n<p>Strong n° 3457 <i>Prononciation [moo-lee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appartenant à un moulin</li>\n<li>fait d'une meule de moulin</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυλικός, ή, όν</b> <span>[ῠ]</span><br><b>      1</b> de meule : λίθος, NT. <i>Marc. 9, 42,</i> pierre meulière, <i>d’où</i> meule ;<br><b>      2</b> qui concerne les molaires, A. TR. <i>p. 214</i>.<br><span><b>Étym</b>. μύλη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυλικος - μυλικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G3458":"<h1>mulos</h1>\n<p>Strong n° 3458 <i>Prononciation [moo'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une meule de moulin\n<ol type=\"a\">\n<li>grande meule faite de deux pierres, celle de dessus, celle de dessous</li>\n<li>la pierre « basse » était fixe, celle du dessus tournait, entraînée par un âne</li>\n</ol>\n</li>\n<li>un moulin, le bruit fait par une meule</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μύλος, ου (ὁ)</b> <span>[ῠ]</span><br><b>      1</b> meule, SPT. <i>Ex. 11, 5 ; Deut. 24, 8, etc. ;</i><br><b>      2</b> pierre meulière, LYC. <i>233 ;</i> ANTH. <i>11, 246, 253 ;</i><br><b>      3</b> dent molaire, ARTÉM. <i>1, 31 ;</i><br><b>      4</b> maladie de femme, MOSCHION <i>Mul. pass. c. 135</i>.<br><span><b>Étym</b>. <i>cf</i>. μύλη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυλος - μύλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G3459":"<h1>mulon</h1>\n<p>Strong n° 3459 <i>Prononciation [moo'-lone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le lieu où tourne la meule</li>\n<li>la maison de la meule, le moulin</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυλών, ῶνος (ὁ)</b> <span>[ῠ]</span> endroit où se trouve la meule, moulin, THC. <i>6, 22 ;</i> EUR. <i>Cycl. 240 ;</i> ARSTT. <i>Rhet. 3, 10</i>.<br><span><b>Étym</b>. μύλη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυλον - μύλων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G3460":"<h1>Mura</h1>\n<p>Strong n° 3460 <i>Prononciation [moo'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Myra = « myrrhe : jus de myrte »\n<ol><li>importante ville de Lycie, sur la côte sud-ouest d'Asie Mineure, bâtie sur une falaise, à l'entrée d'une gorge, à environ 3 km de la mer. Nom moderne : Dembre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Μύρα, ας (ἡ)</b> <i>ou</i> <b>ων (τὰ)</b> Myra <i>ou</i> Myres, <i>v. de Lycie,</i> PLUT. <i>Sol. an. 23 ;</i> SIB. <i>4, 109</i>.<br><br>\n<b>μύρα</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μυρα - Μύρα</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3461":"<h1>murias</h1>\n<p>Strong n° 3461 <i>Prononciation [moo-ree'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mille, milliers</li>\n<li>une multitude innombrable, un nombre illimité</li>\n<li>des guerriers en très grand nombre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυριάς, άδος</b> <span>[ῡᾰδ]</span><br><b>   I</b> <i>adj. f</i>. au nombre de 10 000, <i>càd</i>. en nombre infini, EUR. <i>Rhes. 913 ;</i><br><b>   II</b> <i>subst</i>. ἡ μυριάς :<br><b>      1</b> nombre de 10 000, myriade, HDT. <i>7, 60 ; particul</i>. quantité de 10 000 médimnes, HDT. <i>3, 91 ;</i> DÉM. <i>20, 32, ou</i> drachmes, AR. <i>Eq. 829 ;</i><br><b>      2</b> nombre infini, foule innombrable, ESCHL. <i>Pers. 927 ;</i><br><b>      3</b> <i>au plur</i>. EUR. <i>Ph. 830, etc. ;</i> AR. <i>Vesp. 1010 ;</i> PLAT. <i>Leg. 804</i> e.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. pl. att</i>. μυριαδῶν, <i>non</i> μυριάδων, CHŒROB. <i>t. 2, p. 458, 29</i>.<br><span><b>Étym</b>. μυρίος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυριας - μυριάς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>Hébreux (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G3462":"<h1>murizo</h1>\n<p>Strong n° 3462 <i>Prononciation [moo-rid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>oindre, embaumer, parfumer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυρίζω</b> <span>[ῠ]</span> oindre de parfums, parfumer, ANTIPH. (<i>Com. fr. 3, 81</i>) ; AR. <i>Pl. 529,</i> LYS. <i>938 ; au pass</i>. AR. <i>Eccl. 1117 ; au pass</i>. être parfumé, odorant, HDT. <i>1, 195 ;</i> ATH. <i>565</i> c ; PLUT. <i>M. 142</i> a, <i>693</i> b : ALC. <i>et</i> ALEX. (ATH. <i>691</i> b, e) ; MÉN. (ATH. <i>172</i> c).<br><span><b>Étym</b>. μύρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυριζω - μυρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G3463":"<h1>murioi</h1>\n<p>Strong n° 3463 <i>Prononciation [moo'-ree-oi]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>innombrable, qu'on ne peut compter</li>\n<li>dix mille</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυρίος, α, ον</b> <span>[ῡ, <i>non</i> ῠ, DRAC. <i>p. 65, 19</i>]</span><br><b>   I</b> très nombreux, innombrable :<br><b>      1</b> <i>en parl. de pers. ou de choses qui se comptent :</i> δμῶες μάλα μυρίοι, OD. <i>17, 422,</i> des serviteurs en nombre infini ; μυρία ἄλγεα, IL. <i>1, 2,</i> des douleurs sans nombre ; μυρίαι ἐπὶ μυρίαις, PLAT. <i>Leg. 676</i> b ; <i>cf</i>. PLAT. <i>Theæt. 155</i> c (des villes) par milliers et par milliers ; μυρία ἐπὶ μυρίοις, DH. <i>Rhet. 7, 4, p. 273, 5</i> (des spectacles) par milliers et par milliers ; <i>collectiv. au sg</i>. ὄψις μυρίη, HDT. <i>2, 136,</i> variété infinie de choses à voir ;<br><b>      2</b> <i>en parl. de choses abstraites :</i> μυρίος χρόνος, PD. <i>I. 4, 31,</i> temps infini ; μυρίον κλέος, THCR. <i>Epigr. 19, 2,</i> gloire infinie ; μυρία πενία, PLAT. <i>Ap. 23</i> c, extrême pauvreté ; θώϋμα μυρίον, HDT. <i>2, 148,</i> merveille infinie ; <i>adv</i>., μυρίῳ βέλτιον, PLAT. <i>Rsp. 520</i> c, mille fois mieux ; μυρίῳ διαφέρειν, PLAT. <i>Leg. 773</i> a, <i>etc</i>. l’emporter mille fois ;<br><b>   II</b> dix mille : μυρία ἵππος, ESCHL. <i>Pers. 302 ;</i> μυρίη ἵππος, HDT. <i>1, 27 ; ou</i> ἀσπίς, XÉN. <i>An. 1, 7, 10,</i> corps de 10 000 chevaux <i>ou</i> de 10 000 boucliers ; <i>en ce sens on écrit au plur. avec changement d’accent imaginé par les grammairiens</i> μύριοι, αι, α.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. μυρίος, A. PL. <i>40, 4</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυριοι - μυρίος</font>\n<br><br>pluriel d'un mot primaire, (du sens de beaucoup)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G3464":"<h1>muron</h1>\n<p>Strong n° 3464 <i>Prononciation [moo'-ron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>onguent, parfum, huile odorante</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μύρον, ου (τὸ) :<br>      1</b> parfum liquide, huile <i>ou</i> essence parfumée, ARCHIL. (ATH. <i>688</i> c) ; EUR. <i>Or. 1112 ;</i> AR. <i>Lys. 47 ;</i> PLUT. <i>Artax. 22, etc. ;</i> EL. <i>V.H. 12, 31 ; fig. t. de tendresse,</i> ANTH. <i>5, 113 ;</i><br><b>      2</b> lieu où l’on vend ces parfums, marché aux parfums, AR. <i>Eq. 1375</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυρον - μύρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 13 versets de 5 livres bibliques (NT).\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (4)</li>\n<li>Jean (4)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3465":"<h1>Musia</h1>\n<p>Strong n° 3465 <i>Prononciation [moo-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Mysie (Angl. Mysia) = « territoire des arbres de la plage »\n<ol><li>province d'Asie Mineure sur la côte de la Mer Egée, entre la Lydie et l'Hellespont ; elle incluait les villes de Pergame, Troas, et Assos</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Μυσία, ας (ἡ)</b> <span>[ῡ]</span> Mysie :<br><b>      1</b> <i>contrée de l’Asie Mineure,</i> HDT. <i>1, 160, etc. ;</i> XÉN. <i>An. 7, 8, 8, etc. ;</i><br><b>      2</b> Mœsie, <i>contrée voisine de l’Illyrie,</i> PLUT. <i>Oth. 4, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. Μυσίη, HDT. <i>l. c. Dans les inscr. att. Μυσία se construit avec l’article,</i> CIA. <i>1, 37, z, 6 (425 av. J.C.), ou sans article,</i> CIA. <i>1, 245, 14 (435 av. J.C.) ; v. Meisterh. p. 186, 15</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μυσια - Μυσία</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G3466":"<h1>musterion</h1>\n<p>Strong n° 3466 <i>Prononciation [moos-tay'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chose cachée, un secret, un mystère\n<ol type=\"a\">\n<li>généralement les mystères, les secrets de la religion, confiés seulement aux initiés, et non au commun des mortels</li>\n<li>chose cachée ou secrète, non évidente à la compréhension</li>\n<li>un but ou conseil caché\n<ol>\n<li>volonté secrète\n<ol type=\"a\">\n<li>de l'homme</li>\n<li>de Dieu : les conseils secrets qui conduisent Dieu à agir avec justice, qui sont cachés aux impies et méchants, mais sont clairs aux hommes pieux</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>dans les écrits des rabbins, ce mot dénote un sens mystique ou caché; dans un récit de l'A.T, il s'agit d'une image ou une forme vue dans une vision, d'un songe</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυστήριον, ου (τὸ) :<br>   I</b> mystère, <i>d’où :</i><br><b>      1</b> chose secrète, mystérieuse, SOPH. <i>fr. 493 ;</i> PLAT. <i>Theæt. 156</i> a ;<br><b>      2</b> cérémonie religieuse secrète, <i>d’ord. au plur</i>. HDT. <i>2, 51 ;</i> XÉN. <i>Hell. 1, 4, 14 ;</i> THC. <i>6, 28 ;</i> PLAT. <i>Men. 76</i> e ; <i>à Athènes,</i> les mystères d’Éleusis <i>en l’honneur de Dèmèter :</i> (τὰ μικρὰ μ. les petits mystères, <i>en l’honneur de Perséphonè, dans le mois Anthestériôn ;</i> τὰ μεγάλα μ. les grands mystères, <i>en l’honneur de Dèmèter, dans le mois Boèdromiôn</i>) EUR. <i>Suppl. 173 ;</i> AR. <i>Ran. 887 ;</i><br><b>      3</b> <i>t. eccl</i>. les saints mystères, NT. <i>Matth. 13, 11 ; 1Cor. 14, 2 ; 2Thess. 2, 7, etc. ; en parl. du mystère de l’Incarnation,</i> NYSS. <i>2, 73 Migne ; du mystère de l’Eucharistie,</i> BAS. <i>4, 669 ;</i> NYSS. <i>3, 268, etc. edd. Migne ; du sacrement du baptême,</i> CLÉM. <i>2, 112 ;</i> NAZ. <i>2, 400 Migne ; en parl. de l’Évangile,</i> NT. <i>Eph. 6, 19, etc. ;</i><br><b>   II</b> remède contre la toux, A. TR. <i>5, 248</i>.<br><span><b>Étym</b>. μύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυστηριον - μυστήριον</font>\n<br><br>vient d'un dérivé de 'muo' (fermer la bouche)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 27 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (5)</li>\n<li>Ephésiens (6)</li>\n<li>Colossiens (4)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G3467":"<h1>muopazo</h1>\n<p>Strong n° 3467 <i>Prononciation [moo-ope-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>voir faiblement, voir seulement ce qui est proche, avoir la vue courte être myope</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μυωπάζω</b>, avoir la vue courte, être myope, NT. <i>2Petr. 1, 9</i>.<br><span><b>Étym</b>. μυώψ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μυωπαζω - μυωπάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3468":"<h1>molops</h1>\n<p>Strong n° 3468 <i>Prononciation [mo'-lopes]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une meurtrissure, une marque, blessure d'où coule du sang</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μώλ·ωψ, ωπος (ὁ)</b> marque de coups, meurtrissure, PLUT. <i>M. 46</i> d ; <i>d’ord. au plur</i>. HYPÉR. (POLL. <i>3, 79</i>) ; ARSTT. <i>Probl. 9, 1 ;</i> PLUT. <i>M. 634</i> c, <i>etc</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μωλωψ - μώλωψ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3469":"<h1>momaomai</h1>\n<p>Strong n° 3469 <i>Prononciation [mo-mah'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>blâmer, trouver une faute, se moquer de, railler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μωμάομαι-ῶμαι</b> <span>(<i>f</i>. ήσομαι, <i>ao</i>. ἐμωμησάμην, <i>pf. inus</i>.)</span> blâmer, railler, se moquer de, <i>acc</i>. IL. <i>3, 412 ;</i> SIM. AM. <i>fr. 7, 113 ;</i> ESCHL. <i>Ag. 277 ;</i> A. RH. <i>3, 794 ;</i> THCR. <i>Idyl. 9, 24, etc. ;</i> LUC. <i>H. conscr. 33</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Au sens pass. seul. ao</i>. ἐμωμήθην, NT. <i>2Cor. 6, 3. Ao. dor. 3 sg</i>. μωμάσατο <span>[μᾱ]</span> THCR. <i>Idyl. 9, 24</i>.<br><span><b>Étym</b>. μῶμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μωμαομαι - μωμάομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G3470":"<h1>momos</h1>\n<p>Strong n° 3470 <i>Prononciation [mo'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>souillure, tache, disgrâce\n<ol type=\"a\">\n<li>censure</li>\n<li>insulte\n<ol>\n<li>des hommes qui sont en disgrâce de la société</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μῶμος, ου (ὁ) :<br>      1</b> blâme, reproche, critique, OD. <i>2, 86 ;</i> PD. <i>O. 6, 74 ; P. 1, 82 ;</i> SIM. AM. <i>fr. 7, 84 ;</i> SOPH. (STOB. <i>Fl. 29, 1</i>) ;<br><b>      2</b> raillerie, PLUT. <i>M. 820</i> a.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μωμος - μῶμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3471":"<h1>moraino</h1>\n<p>Strong n° 3471 <i>Prononciation [mo-rah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être fou, agir follement\n<ol type=\"a\">\n<li>faire des folies\n<ol>\n<li>prouver qu'une personne ou une chose est folle</li>\n</ol>\n</li>\n<li>d'un goût plat et sans saveur\n<ol>\n<li>d'un sel qui a perdu sa force et sa saveur</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μωραίνω</b> <span>(<i>f</i>. ανῶ, <i>ao</i>. ἐμώρανα, <i>pass. ao</i>. ἐμωράνθην, <i>pf</i>. μεμώραμμαι)</span><br><b>   I <i>intr.</i></b> être hébété, être sot, être fou, agir <i>ou</i> parler follement, EUR. <i>Med. 614, Andr. 674 ;</i> XÉN. <i>Mem. 1, 1, 11 :</i> τι, ESCHL. <i>Pers. 719,</i> en qqe ch. ;<br><b>   II <i>tr</i>.<br>      1</b> émousser, hébéter, NT. <i>1Cor. 1, 20 ;</i><br><b>      2</b> rendre fou, <i>au pass</i>. devenir fou, ARSTT. <i>H.A. 9, 2 ;</i> SPT. <i>2Reg. 24, 10, etc. ;</i> NT. <i>Matth. 5, 13 ; Rom. 1, 22</i>.<br><span><b>Étym</b>. μωρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μωραινω - μωραίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3472":"<h1>moria</h1>\n<p>Strong n° 3472 <i>Prononciation [mo-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>folie, déraison, stupidité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μωρία, ας (ἡ)</b> folie, ESCHL. <i>Ag. 1670 ;</i> THC. <i>4, 64 ; 5, 41 ;</i> PLAT. <i>Leg. 818</i> d, <i>etc. ; particul</i>. désirs impudiques, EUR. <i>Hipp. 644, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. <i>1, 131, 146</i>.<br><span><b>Étym</b>. μωρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μωρια - μωρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (5)</li>\n</ul>\n</td></tr>\n</table>","G3473":"<h1>morologia</h1>\n<p>Strong n° 3473 <i>Prononciation [mo-rol-og-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>propos insensés, bavardage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μωρολογία, ας (ἡ)</b> sottise de celui qui tient un langage insensé, ARSTT. <i>H.A. 1, 11 ;</i> PLUT. <i>M. 504</i> b.<br><span><b>Étym</b>. μωρολόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μωρολογια - μωρολογία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3474":"<h1>moros</h1>\n<p>Strong n° 3474 <i>Prononciation [mo-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>au sens premier : émoussé d'où</li>\n<li>folie, irréfléchi</li>\n<li>impie, sans Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μωρός, ά, όν</b>, <i>att</i>. <b>μῶρος, α, ον</b>, émoussé, hébété, <i>d’où :</i><br><b>   I</b> <i>au phys. :</i><br><b>      1</b> émoussé, <i>en parl. de nerfs,</i> HPC. <i>232, 25 ;</i><br><b>      2</b> fade, insipide, DIOCL. (ORIB. <i>1, 277</i>) ; DIOSC. <i>4, 19 ;</i><br><b>   II</b> <i>au mor</i>. sot, fou, insensé, <i>en parl. de pers</i>. SOPH. <i>El. 890, 1326 ;</i> EUR. <i>Bacch. 369, etc. ; en parl. de choses,</i> SOPH. <i>Aj. 594, O.R. 433 ;</i> EUR. <i>Her. 682, etc. ; subst</i>. τὸ μῶρον, EUR. <i>Hipp. 966,</i> désir impur.<br><span>•<i> Sup</i>. -ότατος, XÉN. <i>An. 3, 2, 13</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. μῶρος, EUR. <i>Med. 61</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μωρος - μωρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G3475":"<h1>Moseus</h1>\n<p>Strong n° 3475 <i>Prononciation [moce-yoos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Moïse (Angl. Moses) = « tiré de »\n<ol><li>le législateur du peuple Juif et dans un certain sens le fondateur de la religion Juive. Il a écrit les cinq premiers livres de la Bible, communément appelés les Livres de Moïse.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μωσηυς</font> &lt; משה - <font face=\"Georgia\">Μωϋσῆς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n80 fois dans 79 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (8)</li>\n<li>Luc (10)</li>\n<li>Jean (13)</li>\n<li>Actes (19)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (3)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (11)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3476":"<h1>Naasson</h1>\n<p>Strong n° 3476 <i>Prononciation [nah-as-sone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Naasson (Angl. Nahshon) = « enchanteur »\n<ol><li>un ancêtre de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναασσων</font> &lt; נחשון - <font face=\"Georgia\">Ναασσών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3477":"<h1>Naggai</h1>\n<p>Strong n° 3477 <i>Prononciation [nang-gah'-ee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Naggaï (Angl. Nagge) = « illumination »\n<ol><li>un ancêtre de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναγγαι</font> &lt; נגי - <font face=\"Georgia\">Ναγγαί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3478":"<h1>Nazareth</h1>\n<p>Strong n° 3478 <i>Prononciation [nad-zar-eth']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Nazareth = « verdoyant, germe, rejeton » ou « protectrice, gardienne »\n<ol><li>résidence habituelle et ville de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ναζαρέτ (τὸ)</b> <i>indécl</i>. Nazareth, <i>v. de Galilée,</i> NT. <i>Matth. 2, 23, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναζαρεθ - Ναζαρά</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (5)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3479":"<h1>Nazarenos</h1>\n<p>Strong n° 3479 <i>Prononciation [nad-zar-ay-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un habitant de Nazareth</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ναζαρηνός, οῦ</b>, <i>adj. m</i>. de Nazareth, Nazaréen, NT. <i>Marc. 14, 67</i>.<br><span><b>Étym</b>. Ναζαρέτ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναζαρηνος - Ναζαρηνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3480":"<h1>Nazoraios</h1>\n<p>Strong n° 3480 <i>Prononciation [nad-zo-rah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Nazaréen (Angl. Nazarite) = « séparé, consacré à Dieu »\n<ol>\n<li>un habitant de Nazareth</li>\n<li>un titre donné à Jésus dans le N.T., titre messianique</li>\n<li>nom donné aux chrétiens par les Juifs (<a class=\"ref\" data-r=\"ACT24.5\">Actes 24.5</a>)</li>\n<li>Le Nazaréen. Etymologie discutée, soit de l'Hébreu נזר : consacré, voué, soit par assimilation : habitant de Nazareth</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ναζωραῖος, ου</b>, <i>adj. m. c</i>.  NT. <i>Matth. 2, 23 ; 2, 165</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναζωραιος - Ναζωραῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Actes (7)</li>\n</ul>\n</td></tr>\n</table>","G3481":"<h1>Nathan</h1>\n<p>Strong n° 3481 <i>Prononciation [nath-an']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Nathan = « il a donné »\n<ol><li>un des quatre fils de David qui lui fut donné par Bath-Schua</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναθαν</font> &lt; נתן - <font face=\"Georgia\">Ναθάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3482":"<h1>Nathanael</h1>\n<p>Strong n° 3482 <i>Prononciation [nath-an-ah-ale']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>Un disciple intime de Jésus Christ, il est communément pensé qu'il est également Barthélemy. A été touché par la connaissance surnaturelle de Jésus, et a cru (<a class=\"ref\" data-r=\"JHN1.49\">Jean 1.49</a>).</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναθαναηλ</font> &lt; נתנאל - <font face=\"Georgia\">Ναθαναήλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (6)</li>\n</ul>\n</td></tr>\n</table>","G3483":"<h1>nai</h1>\n<p>Strong n° 3483 <i>Prononciation [nahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>oui, véritablement, vraiment, assurément, c'est cela</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ναί</b>, particule affirmative :<br><b>   I</b> <i>pour fortifier une affirmation :</i> ναὶ δή, IL. <i>1, 286 ;</i> ναὶ μήν, ARAT. <i>449 ; dor</i>. ναὶ μάν, THCR. <i>Idyl. 27, 25 ;</i> ναὶ μέν, A. RH. <i>2, 151, etc. ;</i> ναὶ μέντοι, LUC. <i>Astr. 14,</i> oui certes ; <i>particul. dans les formules de serment, avec</i> μά : ναὶ μά, PD. <i>N. 11, 24 ;</i> ANAN. (ATH. <i>370</i> b), certes non, <i>etc. ;</i> ναὶ μὰ Δία, THGN. <i>1041 ;</i> XÉN. <i>Hier. 1, 16 ;</i> EUR. <i>Cycl. 555, etc</i>. par Zeus ; ναὶ μὰ τόν (<i>s.-e</i>. θεόν) EL. <i>N.A. 3, 19, etc</i>. par le dieu ; <i>ou sans</i> μά : ναὶ τὰν κόραν, AR. <i>Vesp. 1438,</i> par la vierge ;<br><b>   II</b> <i>dans le dialogue :</i><br><b>      1</b> <i>comme réponse,</i> oui, ESCHL. <i>Pers. 738 ;</i> ANTH. <i>13, 11, etc. ;</i> ναὶ ναί, THCR. <i>Idyl. 4, 54 ;</i> CALL. <i>Cer. 64 ;</i> NT. <i>Matth. 5, 37,</i> oui ! oui ! ;<br><b>      2</b> <i>comme expression d’une concession suivie de reprise avec</i> ἀλλά : ναὶ… ἀλλά, DS. <i>13, 26,</i> oui sans doute… mais.<br><span><b>Étym</b>. <i>p.-ê. indo-europ</i>. *(h₁e)no-, celui-là ; <i>cf</i>. νή.</span><br><br>\n➁ <b>ναΐ</b>, <i>dor. c</i>. <b>νηΐ</b>, <i>dat. sg. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ναι - ναί</font>\n<br><br>particule primaire de forte affirmation</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n33 fois dans 29 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (3)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (6)</li>\n<li>Philémon (1)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G3484":"<h1>Nain</h1>\n<p>Strong n° 3484 <i>Prononciation [nah-in']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Naïn (Angl. Nain) = « beauté »\n<ol><li>village de Galilée située sur le côté nord du Petit Hermon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναιν</font> &lt; נעים - <font face=\"Georgia\">Ναΐν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3485":"<h1>naos</h1>\n<p>Strong n° 3485 <i>Prononciation [nah-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>utilisé pour le temple à Jérusalem, mais seulement pour l'édifice sacré lui-même, (ou sanctuaire) constitué du Lieu Saint, et du Saint des Saints). Dans le Grec classique, c'est le sanctuaire où se trouvait l'image d'or, pour le distinguer de tout le bâtiment</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ναός, οῦ (ὁ)</b> <span>[ᾱ]</span> <i>propr</i>. habitation, <i>particul</i>. habitation d’un dieu, <i>càd. :</i><br><b>      1</b> temple, IL. <i>1, 39, etc. ; fig. dans les Livres saints et les écriv. ecclésiast. en parl. du corps de J.C. assimilé à un temple,</i> NT. <i>Joh. 11, 19, 21, etc. ; ou en parl. des fidèles eux-mêmes qui sont comme le temple de Dieu,</i> NT. <i>1Cor. 3, 16, 17 ;</i><br><b>      2</b> partie intérieure du temple où était placée la statue du dieu, chapelle, sanctuaire, HDT. <i>1, 183 ;</i><br><b>      3</b> sorte de niche portative où était déposée la statuette d’un dieu, <i>en Égypte,</i> HDT. <i>1, 97 ; 2, 63 ;</i> DS. <i>1, 15</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. seul. νεώς jusqu’en 250 av. J.C. ; à partir de cette époque</i> ναός ; <i>p. except. νεώς dans un décret du collège des Dionysiastes du 2<sup>e</sup> siècle av. J.C. ; sous l’empire νεώς et</i> ναός ; <i>v. Meisterh. p. 99, 13 ; dans une inscr. de 346 av. J.C</i>. νειώς, <i>v. Meisterh. p. 36, 5</i>.<br><span><b>Étym</b>. <i>p.-ê. p. proto-grec</i> *nas-wo-, <i>cf</i>. ναίω, « habitation, maison <i>du dieu</i> » ; <i>autrement p.-ê. pré-grec</i>.</span></span><br><br>\n➁ <b>ναός</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ναος - ναός</font>\n<br><br>vient du mot primaire 'naio' (demeurer)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n46 fois dans 40 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (3)</li>\n<li>Luc (4)</li>\n<li>Jean (3)</li>\n<li>Actes (3)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Apocalypse (16)</li>\n</ul>\n</td></tr>\n</table>","G3486":"<h1>Naoum</h1>\n<p>Strong n° 3486 <i>Prononciation [nah-oom']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Nahum (Angl. Naum) = « consolation, qui a compassion »\n<ol><li>fils d'Esli et père d'Amos, dans la généalogie de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναουμ</font> &lt; נחום - <font face=\"Georgia\">Ναούμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3487":"<h1>nardos</h1>\n<p>Strong n° 3487 <i>Prononciation [nar'dos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>nard, la tête ou pointe d'une plante parfumée de l'Inde de l'est, plante appartenant à la famille des Valériannes, produisant un jus à l'odeur délicieuse que les anciens utilisaient (pur ou mélangé) dans la préparation des onguents et parfums les plus précieux</li>\n<li>huile de nard ou onguent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>νάρδος, ου (ἡ) :<br>      1</b> nard, sorte de valériane, <i>plante,</i> TH. <i>H.P. 9, 7, 2 ;</i> DIOSC. <i>1, 6, etc. ;</i><br><b>      2</b> huile de nard, ANTH. <i>6, 250 ;</i> ARÉT. <i>p. 130, 6, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ναρδος - νάρδος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3488":"<h1>Narkissos</h1>\n<p>Strong n° 3488 <i>Prononciation [nar'-kis-sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Narcisse (Angl. Narcissus) = « stupidité »\n<ol><li>quelqu'un qui avait une demeure à Rome, mentionné par Paul en <a class=\"ref\" data-r=\"ROM16.11\">Romains 16.11</a></li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Νάρκισσος, ου (ὁ)</b> Narkissos (Narcisse) <i>fils de Céphise et de la nymphe Leiriopè,</i> LUC. <i>V.H. 2, 17, etc. ;</i> ANTH. <i>11, 76</i>.<br><span><b>Étym</b>. <i>v</i>. νάρκισσος.</span><br><br>\n<b>νάρκισσος, ου (ὁ, ἡ)</b> narcisse, <i>fleur</i>, HH. <i>Cer. 8, 428 ;</i> SOPH. <i>O.C. 684 ;</i> MOSCH. <i>2, 65 ; fém</i>. THCR. <i>Idyl. 1, 133</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναρκισσος - Νάρκισσος</font>\n<br><br>fleur de même nom, vient de 'narke' (stupéfaction, comme « narcotique »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G3489":"<h1>nauageo</h1>\n<p>Strong n° 3489 <i>Prononciation [now-ag-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>subir un naufrage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ναυαγέω-ῶ</b> <span>[ᾱ]</span> faire naufrage, DÉM. <i>933, 11 ;</i> POL. <i>6, 44, 7 ; fig. en parl. de chars dans le stade,</i> DÉM. <i>1410, 10</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ναυηγέω, HDT. <i>7, 236</i>.<br><span><b>Étym</b>. ναυαγός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ναυαγεω - ναυαγέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3490":"<h1>naukleros</h1>\n<p>Strong n° 3490 <i>Prononciation [now'-klay-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>propriétaire d'un navire, maître d'un navire, armateur\n<ol type=\"a\">\n<li>celui qui loue son vaisseau, ou une partie, pour un transport</li>\n<li>capitaine</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ναύ·κληρος, ου (ὁ) :<br>      1</b> armateur <i>ou</i> propriétaire d’un navire, HDT. <i>1, 5 ;</i> SOPH. <i>Ph. 128, 547 ;</i> XÉN. <i>Mem. 3, 9, 11 ;</i> POL. (PLUT. <i>M. 807</i> b) ; <i>p. anal. à Athènes,</i> propriétaire qui loue sa maison, COM. (ATH. <i>558</i> c) ; HYPÉR. (HARP.) ;<br><b>      2</b> celui qui dirige un navire, pilote, ATH. <i>209</i> a ; PLUT. <i>M. 664</i> c ; <i>fig</i>. EUR. <i>Hipp. 1224</i>.<br><span><b>Étym</b>. <i>p. dissimil. p</i>. ναύκραρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ναυκληρος - ναύκληρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3491":"<h1>naus</h1>\n<p>Strong n° 3491 <i>Prononciation [nowce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un navire, bateau de grande dimension</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ναῦς</b>, <i>gén</i>. <b>νηός</b>, <i>att</i>. <b>νεώς (ἡ)</b> navire, vaisseau, HOM. ATT. <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. gén</i>. νεώς CIA. <i>2, add. 1 c, 17 (399 av. J.C.) ; dat</i>. νηΐ, CIA. <i>2, 795, f, 65, 73 (353 av. J.C.) ; acc</i>. ναῦν, CIA. <i>2, 803 e, 36 (342 av. J.C.) ; plur. gén</i>. νεῶν, CIA. <i>2, 965 b, 28 (400/350 av. J.C.) ; dat</i>. ναυσίν, CIA. <i>2, 795, f (353 av. J.C.) ; acc</i>. ναῦς, CIA. <i>2, 795 c, etc. (353 av. J.C.) ; v. Meisterh. p. 112, 7. Déclin. ion. et épq. avec changement d’ᾱ en η, qqf. en</i> ε : νηῦς, IL. <i>20, 247 ;</i> OD. <i>4, 356, etc. ;</i> νηός (<i>rar</i>. νεός <i>ou</i> νεώς, OD. <i>12, 148</i>) ; νηΐ ; νῆα (<i>rar</i>. νέα, OD. <i>9, 283 ; par syniz. en une seule syll</i>. OD. <i>9, 283</i>) ; νηῦν, A. RH. <i>1, 1358 ; plur</i>. νῆες (<i>rar</i>. νέες, IL. <i>2, 509</i>), νηῶν, νηυσί (<i>épq. aussi</i> νήεσσι, <i>rar</i>. νέεσσι, IL. <i>3, 46 ; 19, 135</i>) ; OD. <i>14, 230,</i> νῆας (<i>rar. épq</i>. νέας, IL. <i>13, 101 ;</i> OD. <i>3, 153 ; 14, 258) ; duel inus. Décl. dor. avec maintien d’ᾱ à tous les cas,</i> νᾶς, ναός, ναΐ, νᾶν ; νᾶες, ναῶν, νάεσσι (PD. <i>P. 4, 56</i>), νᾶας ; <i>duel inus. On trouve, en outre, les formes suiv. : nom. pl</i>. ναῦς, DS. <i>13, 13, gén. dat. pl</i>. ναῦφι(ν), IL. <i>2, 794 ;</i> OD. <i>14, 498</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *neh₂u-, bateau ; <i>cf. lat</i>. nāvis, <i>sscr</i>. náuṣ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ναυς - ναῦς</font>\n<br><br>vient de 'nao' ou 'neo' (flotter)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3492":"<h1>nautes</h1>\n<p>Strong n° 3492 <i>Prononciation [now'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un marin, un homme de mer, un matelot</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ναύτης, ου (ὁ) :<br>      1</b> marin, matelot, IL. <i>4, 76, etc. ;</i> OD. <i>1, 171, etc. ;</i> XÉN. <i>Hell. 1, 1, 16, etc. ;</i><br><b>      2</b> <i>p. anal. avec les matelots qui font ensemble une traversée,</i> compagnon, associé, DIONYS. (ATH. <i>443</i> d).<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ναύτας, EUR. <i>Hec. 921</i>.<br><span><b>Étym</b>. ναῦς ; <i>emprunt lat</i>. nauta.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ναυτης - ναύτης</font>\n<br><br>Voir définition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3493":"<h1>Nachor</h1>\n<p>Strong n° 3493 <i>Prononciation [nakh-ore']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Nachor (Angl. Nahor) = « qui renâcle »\n<ol><li>un ancêtre de Christ, de la famille d'Abraham</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναχωρ</font> &lt; נחור - <font face=\"Georgia\">Ναχώρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3494":"<h1>neanias</h1>\n<p>Strong n° 3494 <i>Prononciation [neh-an-ee'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un jeune homme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>νεανίας, οῦ (ὁ)</b> <span>[ᾱᾱ ; <i>qqf. par syniz. νεα- en une seule longue, chez les Att</i>.]</span><br><b>   I</b> <i>adj. m. :</i><br><b>      1</b> jeune, OD. <i>10, 278 ;</i> PD. <i>O. 7, 4 ;</i> EUR. <i>Andr. 605 ;</i> HDT. <i>7, 99 ;</i> XÉN. <i>Cyr. 2, 2, 2 ;</i><br><b>      2</b> qui concerne les jeunes gens, de jeune homme, EUR. <i>Hel. 211 ;</i><br><b>      3</b> semblable à un jeune homme, <i>càd</i>. fort comme un jeune homme, XÉN. <i>Cyr. 1, 3, 6 ; cf</i>. PLAT. <i>Soph. 239</i> d, <i>etc. ; p. suite, en parl. de choses :</i> robuste, <i>en parl. de membres,</i> EUR. <i>Hel. 1578, H.f. 1095 ; en mauv. part :</i> hardi, audacieux, EUR. <i>Alc. 682 ;</i><br><b>   II</b> <i>subst</i>. ὁ ν. jeune homme, ATT. (SOPH. <i>O.C. 335, etc. ;</i> EUR. <i>Suppl. 580, etc</i>.).<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. νεηνίης, OD. <i>10, 278 ; gén</i>. νεηνίεω, HDT. <i>3, 53 ; 7, 99 ;</i> νεανίας, <i>trisyll. c</i>. *νανίας, AR. <i>Vesp. 1069</i>.<br><span><b>Étym</b>. νέος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">νεανιας - νεανίας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G3495":"<h1>neaniskos</h1>\n<p>Strong n° 3495 <i>Prononciation [neh-an-is'-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un jeune homme, un jeune, adolescent\n<ol type=\"a\">\n<li>utilisé pour un jeune serviteur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>νεανίσκος, ου (ὁ)</b> <span>[ᾱ]</span><br><b>      1</b> jeune homme, homme jeune, XÉN. <i>An. 7, 2, 18 ;</i> PLAT. <i>Rsp. 413</i> e, <i>etc. ;</i><br><b>      2</b> serviteur, LUC. <i>Alex. 53</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. νεηνίσκος, HDT. <i>4, 72, 112</i>.<br><span><b>Étym</b>. νεανίας.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">νεανισκος - νεανίσκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G3496":"<h1>Neapolis</h1>\n<p>Strong n° 3496 <i>Prononciation [neh-ap'-ol-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Néapolis (Angl. Neapolis) = « nouvelle ville »\n<ol><li>cité maritime de Macédoine, port de la ville de Philippes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Νεά·πολις, εως (ἡ)</b> <span>[ᾱ]</span> Néapolis (<i>propr</i>. Nouvelle Ville <i>ou</i> Quartier Neuf, <i>p. opp. à</i> Παλαίπολις) <i>n. de plus. villes en Égypte,</i> HDT. <i>2, 91 ; en Libye,</i> THC. <i>7, 50, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. Νεάπολις, CIA. <i>1, 230-240 (450/440 av. J.C.) ; ou en deux mots sans article :</i> ἐν Νέᾳ πόλῃ, CIA. <i>4, 51, f, 24 (410 av. J.C.) ; ttef. ethnique att</i>. Νεοπολίτης (<i>v</i>. Νεαπολίτης) ; <i>v. Meisterh. p. 91, 9 ; pour l’écriture en deux mots, v. Meisterh. p. 186, 18</i>.<br><span><b>Étym</b>. νέος, πόλις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Νεαπολις - Νέαπόλις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3497":"<h1>Neeman</h1>\n<p>Strong n° 3497 <i>Prononciation [neh-eh-man']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Naaman le Syrien = « agréable »\n<ol><li>commandant en chef de l'armée de Syrie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ναιμαν</font> &lt; נעמן - <font face=\"Georgia\">Ναιμάν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3498":"<h1>nekros</h1>\n<p>Strong n° 3498 <i>Prononciation [nek-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>réellement\n<ol type=\"a\">\n<li>celui qui a rendu son dernier souffle, sans vie</li>\n<li>décédé, parti, celui dont l'âme est dans le Hadès</li>\n<li>sans vie, qui a perdu la vie, inanimé</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>spirituellement mort\n<ol>\n<li>destitué de la vie qui reconnaît et se dévoue à dieu, qui se donne aux péchés, à la mort</li>\n<li>inactif dans la réalisation de ce qui est droit</li>\n</ol>\n</li>\n<li>destitué de force ou pouvoir, inactif, inopérant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>νεκρός, ά, όν :<br>      1</b> mort, OD. <i>11, 475, etc. ;</i> οἱ νεκροί, les morts, AR. <i>Ran. 760 ;</i> PLAT. <i>Leg. 959</i> b, <i>etc. ; en parl. d’animaux,</i> PD. <i>fr. 203 Bgk ; en parl. de choses,</i> M. ANT. <i>2, 12, etc. ;</i> νεκρὴ θάλασσα, ORPH. <i>Arg. 1080 ;</i> PAUS. <i>5, 7, 4 et 5,</i> la mer Morte ;<br><b>      2</b> <i>subst</i>. ὁ νεκρός, le cadavre, OD. <i>12, 13 ; avec un gén</i>. HDT. <i>2, 89, 90 ;</i> XÉN. <i>Cyr. 7, 3, 4, etc. ;</i> ESCHL. <i>Sept. 1013, etc. ;</i> τὸ νεκρόν, <i>m. sign. avec le gén</i>. PLUT. <i>M. 773</i> d.<br><span>•<i> Cp</i>. νεκρότερος, ANTH. <i>11, 135,</i> plus réellement mort.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. νεκρός, DIPH. (<i>Com. fr. 4, 429</i>).<br><span><b>Étym</b>. <i>R. indo-europ</i>. *neḱ-(u)-, mort violente, cadavre ; <i>cf</i>. νέκυς, <i>lat</i>. necāre, nex.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">νεκρος - νεκρός</font>\n<br><br>vient apparemment de 'nekus' (cadavre)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n130 fois dans 121 versets de 18 livres bibliques (NT)\n<ul>\n<li>Matthieu (12)</li>\n<li>Marc (7)</li>\n<li>Luc (14)</li>\n<li>Jean (8)</li>\n<li>Actes (17)</li>\n<li>Romains (16)</li>\n<li>1 Corinthiens (14)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (7)</li>\n<li>Jacques (4)</li>\n<li>1 Pierre (4)</li>\n<li>Apocalypse (13)</li>\n</ul>\n</td></tr>\n</table>","G3499":"<h1>nekroo</h1>\n<p>Strong n° 3499 <i>Prononciation [nek-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre à mort, pousser à la mort, tuer</li>\n<li>usé de corps\n<ol type=\"a\">\n<li>d'un vieil homme impotent</li>\n</ol>\n</li>\n<li>priver de puissance, détruire la force de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>νεκρόω-ῶ :<br>      1</b> faire mourir, <i>d’où au pass</i>. mourir, ANTH. <i>App. 313, 5 ;</i> NT. <i>Rom. 4, 19 ; Hebr. 11, 12 ;</i><br><b>      2</b> rendre comme mort, mortifier, paralyser, NT. <i>Col. 3, 5</i>.<br><span><b>Étym</b>. νεκρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">νεκροω - νεκρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>"};
